from (values
('mcq', 1, 'يمثل المخطط الآتي تفاعلًا لأحد الألكينات. إلى أي أنواع التفاعلات العضوية يُصنَّف هذا التفاعل؟', null, '[{"src":"qimg/chem22/c5-l4-pentene-h2.svg","alt":"معادلة تفاعل مكتوبة بالصيغ البنائية المكثفة من اليسار إلى اليمين: CH₃–CH=CH–CH₂–CH₃ (سلسلة من خمس ذرات كربون فيها رابطة ثنائية بين ذرتي الكربون الثانية والثالثة) + H–H (جزيء هيدروجين) → CH₃–CH₂–CH₂–CH₂–CH₃ (سلسلة من خمس ذرات كربون كل الروابط بينها أحادية)."}]'::jsonb, '["تفاعل إضافة","تفاعل حذف","تفاعل استبدال","تفاعل تكثف"]'::jsonb, 'تطبيق', 'تصنيف تفاعل من معادلته', 'سهل', 'الكتاب ص 186–187 — تفاعلات الإضافة (الهدرجة)'),
('mcq', 2, 'إلى أي أنواع التفاعلات العضوية يُصنَّف التفاعل الآتي؟
