('mcq', 3, 'يمثل المخطط الآتي تفاعل حمض الإيثانويك مع الميثانول. إلى أي أنواع التفاعلات العضوية يُصنَّف؟', null, '[{"src":"qimg/chem22/c5-l4-ester-methyl.svg","alt":"معادلة تفاعل بالصيغ البنائية المكثفة من اليسار إلى اليمين: حمض الإيثانويك CH₃–C(=O)–OH (ذرة كربون مرتبطة بمجموعة CH₃ وبذرة أكسجين برابطة ثنائية وبمجموعة OH) + ميثانول CH₃–OH → إيثانوات الميثيل CH₃–C(=O)–O–CH₃ (ذرة الكربون مرتبطة بذرة أكسجين برابطة ثنائية وبذرة أكسجين أخرى برابطة أحادية تتصل بمجموعة CH₃) + ماء H–O–H."}]'::jsonb, '["تفاعل إضافة","تفاعل تكثف","تفاعل استبدال","تفاعل أكسدة واختزال"]'::jsonb, 'تطبيق', 'تصنيف تفاعل من معادلته', 'سهل', 'الكتاب ص 189 — تفاعلات التكثف'),
('mcq', 4, 'إلى أي أنواع التفاعلات العضوية يُصنَّف احتراق الإيثان الممثل بالمعادلة الآتية؟
2C₂H₆ + 7O₂ → 4CO₂ + 6H₂O', null, null, '["تفاعل حذف","تفاعل إضافة","تفاعل تكثف","تفاعل أكسدة واختزال"]'::jsonb, 'تطبيق', 'تصنيف تفاعل من معادلته', 'متوسط', 'الكتاب ص 189 — تفاعلات الأكسدة والاختزال (الاحتراق)'),
('mcq', 5, 'أي التفاعلات الآتية يُصنَّف تفاعل حذف؟', null, null, '["CH₂=CH₂ + HBr → CH₃CH₂Br","CH₃CH₂Br → CH₂=CH₂ + HBr","CH₃CH₂Br + OH⁻ → CH₃CH₂OH + Br⁻","CH₃CH₃ + Br₂ → CH₃CH₂Br + HBr"]'::jsonb, 'تطبيق', 'تمييز نوع تفاعل من بين معادلات', 'متوسط', 'الكتاب ص 184–185 — تفاعلات الحذف'),
('mcq', 6, 'قال طالب: «التفاعل الآتي تفاعل حذف لأن HBr يظهر في النواتج».
CH₃CH₂CH₂Br + NH₃ → CH₃CH₂CH₂NH₂ + HBr
ما التصنيف الصحيح لهذا التفاعل؟', null, null, '["تفاعل حذف لأن ذرتي H وBr نُزعتا من ذرتي كربون متجاورتين","تفاعل تكثف لأن جزيئين اتحدا وخرج جزيء صغير","تفاعل استبدال لأن مجموعة NH₂ حلت محل ذرة البروم","تفاعل إضافة لأن NH₃ أُضيفت إلى هاليد الألكيل"]'::jsonb, 'تحليل', 'تحليل تصنيف مقترح', 'صعب', 'الكتاب ص 172 — تفاعلات الاستبدال (تكوين الأمينات)'),
('mcq', 7, 'يبين الجدول الآتي أربعة تفاعلات عضوية. أي البدائل يصنفها تصنيفًا صحيحًا بالترتيب (1، 2، 3، 4)؟', '{"headers":["رقم التفاعل","التفاعل"],"rows":[["1","2-بروبانول ← بروبين + ماء"],["2","بيوتين حلقي + ماء ← بيوتانول حلقي"],["3","CH₃CH₂Cl + OH⁻ → CH₃CH₂OH + Cl⁻"],["4","2-بروبانول + (O) ← 2-بروبانون + ماء"]]}'::jsonb, null, '["حذف، استبدال، إضافة، أكسدة واختزال","إضافة، إضافة، استبدال، تكثف","حذف، إضافة، حذف، أكسدة واختزال","حذف، إضافة، استبدال، أكسدة واختزال"]'::jsonb, 'تحليل', 'تصنيف مجموعة تفاعلات', 'صعب', 'الكتاب ص 184–190 — تصنيف تفاعلات المواد العضوية'),
('essay', 1, 'صنّف كل تفاعل من التفاعلات الآتية إلى: استبدال، أو إضافة، أو حذف، أو أكسدة واختزال، أو تكثف، مع ذكر سبب كل تصنيف:
(a) 2-بيوتين + هيدروجين ← بيوتان
(b) بروبان + فلور ← 2-فلورو بروبان + فلوريد الهيدروجين
(c) 2-بروبانول ← بروبين + ماء
(d) بيوتين حلقي + ماء ← بيوتانول حلقي', null, null, null, 'تطبيق', 'تصنيف وتعليل', 'سهل', 'الكتاب ص 203 — تقويم الفصل (س49)'),
('essay', 2, 'قارن بين تفاعلات الإضافة وتفاعلات الحذف من حيث: (1) ما يحدث للروابط بين ذرات الكربون، (2) نوع المركب المتفاعل والناتج في كل منهما، (3) العلاقة بين النوعين. ثم اكتب معادلة تمثل مثالًا على كل نوع.', null, null, null, 'تحليل', 'مقارنة', 'متوسط', 'الكتاب ص 184–186 — تفاعلات الحذف والإضافة'),
('essay', 3, 'أجب عما يأتي:
(a) اكتب المعادلة العامة لتكوين الإستر من حمض كربوكسيلي وكحول، وحدد نوع هذا التفاعل، وفسّر علاقته بتفاعلات الحذف.
(b) اكتب معادلة تحول الميثان إلى ميثانول بوجود الأكسجين (O) من مصدر مثل أكسيد النحاس II، وحدد نوع هذا التفاعل مع التعليل.
(c) اذكر فائدة واحدة لتصنيف التفاعلات العضوية في أنواع.', null, null, null, 'تحليل', 'تفسير تصنيف', 'صعب', 'الكتاب ص 188–189 — الأكسدة والاختزال والتكثف، وص 203 (س47)')
