insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'الهدرجة إضافة جزيء H₂ إلى ذرتي الكربون في الرابطة الثنائية، فيتحول الإيثين CH₂=CH₂ إلى الإيثان CH₃–CH₃: CH₂=CH₂ + H₂ → CH₃–CH₃.', '["هذه معادلة حذف الهيدروجين، وهي عكس الهدرجة؛ إذ يتحول فيها الإيثان إلى إيثين.","هذه معادلة إضافة الماء التي تنتج كحولًا، لا الهدرجة.","","هذه معادلة حذف هيدروجين من الإيثين لتكوين رابطة ثلاثية، والهدرجة تضيف H₂ ولا تنزعه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-14T13:39:20.704Z"}'::jsonb),
('mcq', 2, 0, 'في حذف الماء تُنزع مجموعة OH من ذرة كربون وذرة H من ذرة الكربون المجاورة فتتكون رابطة ثنائية ويخرج جزيء ماء H₂O؛ وعدد الذرات في الطرفين: C₅H₁₂O = C₅H₁₀ + H₂O.', '["","خروج H₂ يميز حذف الهيدروجين من الألكانات، ولو خرج H₂ لبقيت ذرة أكسجين غير محسوبة في النواتج.","لا يخرج أيون هيدروكسيد منفردًا؛ فذرة H المنزوعة تتحد مع OH ليتكون جزيء ماء مستقر، وإلا اختلفت الشحنة والذرات بين الطرفين.","لا يُنتج حذف الماء غاز الأكسجين، والمعادلة لا تتوازن بـ O₂ لأن ذرتي الهيدروجين المنزوعتين تبقيان دون حساب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.705Z"}'::jsonb),
('mcq', 3, 3, 'في تكوين الإستر RCOOH + R′OH → RCOOR′ + H₂O تبقى مجموعة الأسيل CH₃CH₂CO من الحمض وترتبط بأكسجين الكحول الذي يحمل مجموعة الإيثيل، فالناتج بروبانوات الإيثيل CH₃CH₂COOCH₂CH₃ مع جزيء ماء؛ والذرات متوازنة (C₅H₁₂O₃ في الطرفين).', '["الجزيء الصغير الذي يُفقد في هذا التكثف هو الماء لا الهيدروجين، والمعادلة بهذه الصورة غير موزونة (تنقص ذرة أكسجين).","هذه صيغة إيثر لا إستر؛ فقد اختفت ذرة أكسجين الكربونيل، والمعادلة غير موزونة.","هذا إيثانوات البروبيل؛ عُكس فيه دور المتفاعلين، فالحمض هنا ثلاثي الكربون والكحول ثنائي الكربون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.705Z"}'::jsonb),
('mcq', 4, 1, 'في الإضافة ترتبط ذرتا الكلور بذرتي الكربون 3 و4 المكونتين للرابطة الثنائية فتتحول إلى أحادية، ويتكون ناتج واحد هو CH₃CH₂CHClCHClCH₂CH₃ (3، 4-ثنائي كلورو هكسان).', '["هذه معادلة استبدال: حلت ذرة كلور محل ذرة هيدروجين وبقيت الرابطة الثنائية، والناتج ليس ثنائي كلورو هكسان.","","في الإضافة لا يخرج H₂ ولا تبقى الرابطة الثنائية؛ هذا الناتج ما زال ألكينًا.","هذا ناتج إضافة HCl لا Cl₂، والمعادلة غير موزونة لأن ذرة كلور اختفت من النواتج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-14T13:39:20.705Z"}'::jsonb),
('mcq', 5, 2, '1-بروبانول كحول أولي (OH على ذرة كربون طرفية)، فيتأكسد أولًا إلى ألدهيد بالعدد نفسه من ذرات الكربون هو البروبانال CH₃CH₂CHO، مع خروج الماء؛ والذرات متوازنة: C₃H₈O + O = C₃H₆O + H₂O.', '["CH₃COCH₃ هو 2-بروبانون، وهو ناتج أكسدة الكحول الثانوي 2-بروبانول لا 1-بروبانول.","هذه معادلة حذف الماء التي تنتج ألكينًا، وليست أكسدة؛ فلا يوجد عامل مؤكسد (O).","","الحمض الكربوكسيلي ناتج الخطوة الثانية (أكسدة الألدهيد)، والمعادلة بهذه الصورة غير موزونة (ينقص ذرتا هيدروجين)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-14T13:39:20.705Z"}'::jsonb),
('mcq', 6, 3, 'يُنزع من هاليد الألكيل ذرة الهالوجين X وذرة هيدروجين من ذرة الكربون المجاورة، فتتكون رابطة ثنائية (ألكين) ويخرج HX: R–CH₂–CH₂–X → R–CH=CH₂ + HX.', '["هذه المعادلة العامة لاستبدال الهالوجين بمجموعة الهيدروكسيل، وناتجها كحول لا ألكين.","هذه معادلة إضافة HX إلى ألكين، أي تحويل الألكين إلى هاليد ألكيل، وهو عكس المطلوب.","هذه المعادلة العامة لهلجنة الألكان (استبدال)، وهي تُنتج هاليد الألكيل ولا تحوله إلى ألكين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-14T13:39:20.705Z"}'::jsonb),
('mcq', 7, 0, 'يلزم جزيء H₂ لكل رابطة من الرابطتين اللتين تتكسران في الرابطة الثلاثية: الجزيء الأول يحول الألكاين إلى ألكين، والثاني يحول الألكين إلى ألكان. الذرات: C₃H₄ + 2H₂ = C₃H₈.', '["","جزيء H₂ واحد يحول الألكاين إلى ألكين فقط، والمعادلة بهذه الصورة غير موزونة (C₃H₆ في اليسار وC₃H₈ في اليمين).","هذه معادلة صحيحة لكنها تمثل الخطوة الأولى فقط وتنتج البروبين لا البروبان.","ثلاثة جزيئات H₂ تعطي 10 ذرات هيدروجين في المتفاعلات مقابل 8 في البروبان؛ فالمعادلة غير موزونة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.705Z"}'::jsonb),
('essay', 1, null::int, null, null, 'CH₃CH₂COOH + CH₃CH₂OH → CH₃CH₂COOCH₂CH₃ + H₂O. يرتبط أكسجين الكحول (بعد فقده ذرة الهيدروجين) بذرة كربون الكربونيل في الحمض (بعد فقده مجموعة OH)، فيتكون الإستر بروبانوات الإيثيل CH₃CH₂–C(=O)–O–CH₂CH₃. الجزيء المفقود هو الماء H₂O، ويتكون من مجموعة OH من الحمض الكربوكسيلي وذرة H من مجموعة OH في الكحول. والتفاعل من نوع التكثف لأن جزيئين اتحدا في جزيء أكبر مع فقد جزيء ماء.', '["صيغتا المتفاعلين صحيحتان","صيغة الإستر الصحيحة CH₃CH₂COOCH₂CH₃","المعادلة موزونة مع H₂O","اسم الإستر: بروبانوات الإيثيل","الماء من OH الحمض وH الكحول"]'::jsonb, '[]'::jsonb, '[{"element":"صيغ المتفاعلين","marks":1},{"element":"صيغة الإستر والمعادلة الموزونة","marks":2},{"element":"اسم الإستر","marks":1},{"element":"أصل جزيء الماء","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"معادلة صحيحة موزونة، واسم صحيح، وتحديد صحيح لأصل الماء"},{"level":"3–4 درجات","description":"معادلة صحيحة مع نقص في الاسم أو أصل الماء"},{"level":"1–2 درجة","description":"صيغ المتفاعلين أو الناتج فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الناتج إيثانوات البروبيل بعكس دوري الحمض والكحول","نسيان الماء في النواتج","كتابة الإستر CH₃CH₂OCH₂CH₃ (إيثر) بحذف أكسجين الكربونيل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.705Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) CH₃–CH₃ → CH₂=CH₂ + H₂، والناتج الإيثين. (b) CH₃–CH₂–OH → CH₂=CH₂ + H₂O، والناتج الإيثين. (c) CH₃–CHBr–CH₃ → CH₂=CH–CH₃ + HBr، والناتج البروبين. في كل منها نُزعت ذرتان (أو ذرة ومجموعة) من ذرتي كربون متجاورتين فتكونت رابطة ثنائية.', '["(a) معادلة موزونة والناتج إيثين","(b) معادلة موزونة والناتج إيثين","(c) معادلة موزونة والناتج بروبين"]'::jsonb, '[]'::jsonb, '[{"element":"(a)","marks":1},{"element":"(b)","marks":1},{"element":"(c)","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"المعادلات الثلاث صحيحة موزونة مع أسماء النواتج"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان الجزيء الصغير (H₂ أو H₂O أو HBr) في النواتج","كتابة الناتج ألكانًا أو إبقاء ذرة البروم فيه","وضع الرابطة الثنائية بين ذرتي كربون غير متجاورتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-14T13:39:20.706Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) CH₃–CH=CH–CH₃ + H₂ → CH₃–CH₂–CH₂–CH₃ (ألكان: بيوتان). (b) CH₃–CH=CH–CH₃ + H₂O → CH₃–CH(OH)–CH₂–CH₃ (كحول: 2-بيوتانول). (c) CH₃–CH=CH–CH₃ + HBr → CH₃–CHBr–CH₂–CH₃ (هاليد ألكيل: 2-برومو بيوتان). (d) CH₃–CH=CH–CH₃ + Br₂ → CH₃–CHBr–CHBr–CH₃ (ثنائي هاليد الألكيل: 2، 3-ثنائي برومو بيوتان). في كل حالة ترتبط الذرتان (أو الذرة والمجموعة) بذرتي الكربون 2 و3 وتتحول الرابطة الثنائية إلى أحادية.', '["(a) معادلة الهدرجة → ألكان","(b) إضافة الماء → كحول","(c) إضافة HBr → هاليد ألكيل","(d) إضافة Br₂ → ثنائي هاليد الألكيل"]'::jsonb, '[]'::jsonb, '[{"element":"(a)","marks":1},{"element":"(b)","marks":1},{"element":"(c)","marks":1},{"element":"(d)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المعادلات الأربع صحيحة مع نوع كل ناتج"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا: عنصران أو ثلاثة من عناصر الإجابة صحيحة"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إبقاء الرابطة الثنائية في الناتج","إضافة ذرتي البروم إلى ذرة الكربون نفسها","كتابة ناتج إضافة الماء ألدهيدًا أو إيثرًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-14T13:39:20.706Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C5-L4-O02') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C5-L4-O03'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يمثل المخطط الآتي تفاعل البنتين الحلقي مع بروميد الهيدروجين. ما الناتج المتوقع لهذا التفاعل؟', null, '[{"src":"qimg/chem22/c5-l4-cyclopentene-hbr.svg","alt":"معادلة غير مكتملة من اليسار إلى اليمين: صيغة هيكلية خطية لحلقة خماسية من ذرات الكربون فيها رابطة ثنائية واحدة، مكتوب تحتها «بنتين حلقي» + HBr مكتوب تحته «بروميد الهيدروجين» → علامة استفهام مكان الناتج."}]'::jsonb, '["1، 2-ثنائي برومو بنتان حلقي","برومو بنتان حلقي","برومو بنتين حلقي وهيدروجين","بنتان حلقي وبروم"]'::jsonb, 'تطبيق', 'توقع ناتج إضافة', 'سهل', 'الكتاب ص 190 — توقع نواتج التفاعلات العضوية'),
('mcq', 2, 'وفق المعادلة العامة لحذف الماء من الكحولات، ما الناتج العضوي لحذف الماء من 1-بيوتانول CH₃CH₂CH₂CH₂OH؟', null, null, '["بيوتان","بيوتانال","1-بيوتاين","1-بيوتين"]'::jsonb, 'تطبيق', 'توقع ناتج حذف', 'سهل', 'الكتاب ص 189–190 — توقع نواتج التفاعلات العضوية'),
('mcq', 3, 'يمثل المخطط الآتي تفاعل 2-كلورو بيوتان مع أيون الهيدروكسيد OH⁻. ما نواتج هذا التفاعل؟', null, '[{"src":"qimg/chem22/c5-l4-2-chlorobutane-oh.svg","alt":"معادلة غير مكتملة بالصيغ البنائية المكثفة: CH₃–CH₂–CH–CH₃ وتتصل ذرة كلور Cl إلى الأسفل بمجموعة CH (ذرة الكربون الثانية من الطرف الأيمن)، أي CH₃CH₂CHClCH₃ + أيون الهيدروكسيد OH⁻ → علامة استفهام مكان النواتج."}]'::jsonb, '["2-بيوتانول وأيون الكلوريد","1-بيوتانول وأيون الكلوريد","2-بيوتانون وكلوريد الهيدروجين","بيوتانال وكلوريد الهيدروجين"]'::jsonb, 'تطبيق', 'توقع ناتج استبدال', 'متوسط', 'الكتاب ص 172 (الجدول 5-3) وص 190 (س19b)'),
('mcq', 4, 'ما النواتج المتوقعة للتفاعل الآتي؟
CH₃CH₂Cl + NH₃ → ?', null, null, '["CH₃CH₂NH₂Cl + H₂","CH₃CH₂NH₃ + Cl₂","CH₃CH₂NH₂ + HCl","CH₃CH₃ + NH₂Cl"]'::jsonb, 'تطبيق', 'توقع نواتج استبدال', 'متوسط', 'الكتاب ص 172 (الجدول 5-3) وص 207 (س1)'),
('mcq', 5, 'يمثل المخطط الآتي إضافة الماء إلى 1-بيوتين، ويمكن أن يتكون فيها ناتجان مختلفان. ما هذان الناتجان؟', null, '[{"src":"qimg/chem22/c5-l4-1-butene-water.svg","alt":"معادلة غير مكتملة: 1-بيوتين CH₂=CH–CH₂–CH₃ (الرابطة الثنائية بين ذرة الكربون الطرفية والذرة المجاورة لها) + ماء H₂O → علامة استفهام مكان النواتج."}]'::jsonb, '["1-بيوتانول وبيوتانال","1-بيوتانول و2-بيوتانول","2-بيوتانول و2-بيوتانون","بيوتان و1-بيوتانول"]'::jsonb, 'تحليل', 'توقع النواتج المحتملة', 'صعب', 'الكتاب ص 186 (الجدول 5-12) وص 190 (س20)'),
('mcq', 6, 'ما الناتج العضوي لتفاعل حمض الإيثانويك CH₃COOH مع 1-بروبانول CH₃CH₂CH₂OH الذي يُفقد فيه جزيء ماء؟', null, null, '["بروبانوات الإيثيل","حمض البنتانويك","2-بنتانون","إيثانوات البروبيل"]'::jsonb, 'تحليل', 'توقع ناتج تكثف', 'متوسط', 'الكتاب ص 181 و189 — الإسترات وتفاعلات التكثف'),
('mcq', 7, 'ما الناتج العضوي المتوقع عند إضافة جزيء واحد فقط من الهيدروجين H₂ إلى 2-بيوتاين CH₃–C≡C–CH₃؟', null, null, '["2-بيوتين","بيوتان","1-بيوتين","2-بيوتانول"]'::jsonb, 'تحليل', 'توقع ناتج هدرجة جزئية', 'صعب', 'الكتاب ص 187 — هدرجة الألكاينات'),
('essay', 1, 'توقع الناتج العضوي لكل تفاعل مما يأتي، واكتب المعادلة الموزونة بالصيغ البنائية (المكثفة أو الهيكلية)، وسمِّ الناتج:
(a) حذف الماء من الإيثانول.
(b) إضافة الماء إلى الهكسين الحلقي.
(c) تفاعل 2-كلورو بروبان مع أيون الهيدروكسيد OH⁻.', null, null, null, 'تحليل', 'توقع نواتج وكتابة معادلات', 'متوسط', 'الكتاب ص 185–190 — توقع نواتج التفاعلات العضوية'),
('essay', 2, 'تمثل الصيغتان الآتيتان 1-بيوتين و2-بيوتين. فسّر لماذا تؤدي إضافة الماء إلى 1-بيوتين إلى تكوين نوعين من النواتج، بينما تُكوّن إضافة الماء إلى 2-بيوتين ناتجًا واحدًا. اكتب صيغ النواتج وأسماءها في الحالتين.', null, '[{"src":"qimg/chem22/c5-l4-butenes.svg","alt":"صيغتان بنائيتان مكثفتان: إلى اليمين 1-بيوتين CH₂=CH–CH₂–CH₃ والرابطة الثنائية بين ذرة الكربون الطرفية والذرة المجاورة لها، وإلى اليسار 2-بيوتين CH₃–CH=CH–CH₃ والرابطة الثنائية بين ذرتي الكربون الوسطيين، فطرفا الرابطة الثنائية فيه متماثلان."}]'::jsonb, null, 'تحليل', 'تفسير وتوقع', 'صعب', 'الكتاب ص 190 — التقويم 5-4 (س20)'),
('essay', 3, 'أُجريت سلسلة التفاعلات الآتية:
1) نُزع الماء من الإيثانول فتكوّن المركب A.
2) أضيف البروم Br₂ إلى المركب A فتكوّن المركب B.
3) تفاعل الإيثانول مع حمض الإيثانويك فتكوّن المركب C وماء.
توقع صيغة كل من A وB وC واسمه، واكتب معادلة كل خطوة، واذكر نوع كل تفاعل.', null, null, null, 'تحليل', 'توقع نواتج سلسلة تفاعلات', 'صعب', 'الكتاب ص 185–189 — الحذف والإضافة والتكثف')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
