select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'التفاعل إضافة HX إلى ألكين: ترتبط ذرة H بإحدى ذرتي الرابطة الثنائية وذرة Br بالأخرى فتتحول الرابطة إلى أحادية، فيتكون هاليد ألكيل واحد هو برومو بنتان حلقي C₅H₉Br.', '["ثنائي البروم ينتج عند إضافة Br₂ لا HBr؛ فجزيء HBr يحمل ذرة بروم واحدة.","","هذا يفترض استبدال ذرة H بذرة Br مع بقاء الرابطة الثنائية، لكن الألكين يتفاعل مع HBr بالإضافة.","هذا يفترض إضافة H₂ وحدها، ولا مصدر لجزيء H₂ ولا يتحرر البروم في هذا التفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-14T13:39:20.706Z"}'::jsonb),
('mcq', 2, 3, 'المعادلة العامة لحذف الماء: R–CH₂–CH₂–OH → R–CH=CH₂ + H₂O؛ تُنزع OH من ذرة الكربون 1 وH من ذرة الكربون 2 فتتكون رابطة ثنائية بينهما: CH₃CH₂CH₂CH₂OH → CH₃CH₂CH=CH₂ + H₂O، والناتج 1-بيوتين.', '["البيوتان مشبع؛ وحذف الماء يكوّن رابطة ثنائية ولا يُنتج ألكانًا.","البيوتانال ناتج أكسدة 1-بيوتانول، لا ناتج حذف الماء منه.","حذف جزيء ماء واحد يكوّن رابطة ثنائية لا ثلاثية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.706Z"}'::jsonb),
('mcq', 3, 0, 'وفق المعادلة العامة R–X + OH⁻ → R–OH + X⁻ تحل مجموعة OH محل ذرة الكلور في الموقع نفسه (ذرة الكربون 2): CH₃CH₂CHClCH₃ + OH⁻ → CH₃CH₂CH(OH)CH₃ + Cl⁻، فالناتجان 2-بيوتانول وأيون الكلوريد.', '["","مجموعة OH تحل محل الكلور على ذرة الكربون نفسها (2) ولا تنتقل إلى ذرة الكربون الطرفية.","الكيتون ناتج أكسدة الكحول الثانوي، ولا يوجد عامل مؤكسد في هذا التفاعل، والكلور يخرج أيون كلوريد لا HCl.","الألدهيد يتطلب مجموعة كربونيل في طرف السلسلة وعاملًا مؤكسدًا، وهذا تفاعل استبدال بسيط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-14T13:39:20.706Z"}'::jsonb),
('mcq', 4, 2, 'هاليد الألكيل يتفاعل مع الأمونيا بالاستبدال وفق R–X + NH₃ → R–NH₂ + HX: تحل مجموعة NH₂ محل ذرة الكلور، وتتحد ذرة الكلور مع ذرة H من الأمونيا لتكوّن HCl؛ فالنواتج إيثيل أمين CH₃CH₂NH₂ وHCl.', '["بقيت ذرة الكلور مرتبطة بالناتج العضوي وخرج H₂، وهذا لا يوافق الاستبدال الذي تخرج فيه ذرة الهالوجين في صورة HX.","المعادلة غير موزونة: يظهر في النواتج ذرتا Cl مقابل ذرة واحدة في المتفاعلات، وCH₃CH₂NH₃ ليس جزيئًا مستقرًا.","","هذا يفترض انتقال ذرة H إلى السلسلة وخروج NH₂Cl، والصحيح أن مجموعة NH₂ ترتبط بذرة الكربون مكان الكلور."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.707Z"}'::jsonb),
('mcq', 5, 1, 'تُضاف H إلى إحدى ذرتي الرابطة الثنائية (C1 وC2) وOH إلى الأخرى؛ فإذا ارتبطت OH بذرة الكربون 1 تكوّن 1-بيوتانول، وإذا ارتبطت بذرة الكربون 2 تكوّن 2-بيوتانول، لأن طرفي الرابطة الثنائية في 1-بيوتين غير متماثلين.', '["البيوتانال ألدهيد ينتج بالأكسدة، وإضافة الماء إلى ألكين تعطي كحولًا فقط.","","2-بيوتانون كيتون ناتج عن أكسدة 2-بيوتانول، لا عن إضافة الماء.","البيوتان ناتج الهدرجة (إضافة H₂) لا إضافة الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.707Z"}'::jsonb),
('mcq', 6, 3, 'RCOOH + R′OH → RCOOR′ + H₂O؛ يبقى من الحمض الجزء CH₃CO (إيثانوات) ومن الكحول مجموعة البروبيل، فالإستر CH₃COOCH₂CH₂CH₃ واسمه إيثانوات البروبيل، ويخرج الماء.', '["هذا الإستر مشتق من حمض البروبانويك والإيثانول؛ أي عُكس فيه دور الحمض والكحول.","تفاعل الحمض مع الكحول يكوّن إسترًا لا حمضًا كربوكسيليًّا أطول.","ناتج التكثف بين الحمض والكحول إستر يحتوي على المجموعة –COO–، لا كيتون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.707Z"}'::jsonb),
('mcq', 7, 0, 'جزيء H₂ الأول يُضاف إلى ذرتي الكربون 2 و3 في الرابطة الثلاثية فتتحول إلى رابطة ثنائية في الموقع نفسه: CH₃–C≡C–CH₃ + H₂ → CH₃–CH=CH–CH₃ (2-بيوتين)، ويلزم جزيء ثانٍ لتكوين البيوتان.', '["","البيوتان يتكون بعد إضافة جزيئين من H₂، أي باستمرار الهدرجة.","الإضافة لا تنقل موقع الرابطة؛ فهي تبقى بين ذرتي الكربون 2 و3.","تكوين الكحول يحتاج إلى إضافة الماء لا الهيدروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.707Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) CH₃CH₂OH → CH₂=CH₂ + H₂O، والناتج إيثين (حذف الماء يكوّن رابطة ثنائية). (b) الهكسين الحلقي C₆H₁₀ + H₂O → C₆H₁₁OH، أي ترتبط H بإحدى ذرتي الرابطة الثنائية وOH بالأخرى فيتكون الهكسانول الحلقي (حلقة سداسية مشبعة تتصل بها مجموعة OH). (c) CH₃CHClCH₃ + OH⁻ → CH₃CH(OH)CH₃ + Cl⁻، والناتج 2-بروبانول (استبدال الهالوجين بالهيدروكسيل).', '["(a) المعادلة والإيثين","(b) المعادلة والهكسانول الحلقي","(c) المعادلة و2-بروبانول وأيون الكلوريد"]'::jsonb, '[]'::jsonb, '[{"element":"(a)","marks":1},{"element":"(b)","marks":1},{"element":"(c)","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"النواتج الثلاثة صحيحة مع معادلات موزونة وأسماء صحيحة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة ناتج (b) هكسان حلقي (خلط إضافة الماء بالهدرجة)","وضع OH في (c) على ذرة كربون طرفية (1-بروبانول)","نسيان الماء في نواتج (a)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.707Z"}'::jsonb),
('essay', 2, null::int, null, null, 'في إضافة الماء تُضاف H إلى إحدى ذرتي الرابطة الثنائية وOH إلى الأخرى. في 1-بيوتين CH₂=CH–CH₂–CH₃ ذرتا الرابطة الثنائية غير متماثلتين (C1 طرفية وC2 داخلية)، فإذا ارتبطت OH بـ C1 نتج 1-بيوتانول CH₂(OH)CH₂CH₂CH₃، وإذا ارتبطت بـ C2 نتج 2-بيوتانول CH₃CH(OH)CH₂CH₃؛ أي ناتجان. أما في 2-بيوتين CH₃–CH=CH–CH₃ فذرتا الرابطة الثنائية متماثلتان (كل منهما مرتبطة بمجموعة CH₃)، فأينما ارتبطت OH يكون الناتج الجزيء نفسه 2-بيوتانول CH₃CH(OH)CH₂CH₃.', '["آلية الإضافة: H لذرة وOH للأخرى","عدم تماثل طرفي الرابطة في 1-بيوتين → 1-بيوتانول و2-بيوتانول","تماثل طرفي الرابطة في 2-بيوتين → 2-بيوتانول فقط","صيغ النواتج وأسماؤها"]'::jsonb, '[]'::jsonb, '[{"element":"آلية الإضافة","marks":1},{"element":"نواتج 1-بيوتين","marks":1},{"element":"ناتج 2-بيوتين وتعليل التماثل","marks":1},{"element":"الصيغ والأسماء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل مبني على تماثل طرفي الرابطة مع صيغ النواتج وأسمائها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا: عنصران أو ثلاثة من عناصر الإجابة صحيحة"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن 2-بيوتين يعطي 2-بيوتانول و3-بيوتانول بوصفهما مركبين مختلفين","كتابة ناتج إضافة الماء ألدهيدًا","عدم ربط عدد النواتج بموقع الرابطة الثنائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.707Z"}'::jsonb),
('essay', 3, null::int, null, null, '1) CH₃CH₂OH → CH₂=CH₂ + H₂O؛ A إيثين، والتفاعل حذف (حذف الماء). 2) CH₂=CH₂ + Br₂ → CH₂Br–CH₂Br؛ B هو 1، 2-ثنائي برومو إيثان، والتفاعل إضافة (هلجنة الرابطة الثنائية). 3) CH₃COOH + CH₃CH₂OH → CH₃COOCH₂CH₃ + H₂O؛ C إيثانوات الإيثيل (إستر)، والتفاعل تكثف.', '["A إيثين ومعادلة الحذف","B 1، 2-ثنائي برومو إيثان ومعادلة الإضافة","C إيثانوات الإيثيل ومعادلة التكثف","نوع كل تفاعل"]'::jsonb, '[]'::jsonb, '[{"element":"A ومعادلته","marks":1},{"element":"B ومعادلته","marks":1},{"element":"C ومعادلته","marks":1},{"element":"أنواع التفاعلات الثلاثة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الصيغ والأسماء والمعادلات والأنواع كلها صحيحة"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا: عنصران أو ثلاثة من عناصر الإجابة صحيحة"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة B برومو إيثان (خلط Br₂ بـ HBr)","تسمية C إيثانوات الميثيل أو نسيان الماء","تصنيف الخطوة 3 استبدالًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.708Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
