('mcq', 5, 'ما التحول الذي يحدث في نوع المركب العضوي خلال تفاعل الهدرجة؟', null, null, '["يتحول الألكين إلى ألكان","يتحول الألكان إلى ألكين","يتحول الألكين إلى كحول","يتحول الكحول إلى ألكين"]'::jsonb, 'فهم', 'تمييز ناتج تفاعل', 'متوسط', 'الكتاب ص 186 — تفاعلات الهدرجة'),
('mcq', 6, 'في المخطط الآتي، أي سهمين يمثلان على الترتيب: حذف الهيدروجين، ثم إضافة الماء؟', null, '[{"src":"qimg/chem22/c5-l4-cycle.svg","alt":"ثلاث صيغ بنائية كاملة من اليسار إلى اليمين: إيثان CH₃–CH₃، ثم إيثين CH₂=CH₂، ثم إيثانول CH₃–CH₂–OH. بين الإيثان والإيثين سهمان: السهم (1) في الأعلى يتجه من الإيثان إلى الإيثين، والسهم (2) في الأسفل يتجه من الإيثين إلى الإيثان. وبين الإيثين والإيثانول سهمان: السهم (3) في الأعلى يتجه من الإيثين إلى الإيثانول، والسهم (4) في الأسفل يتجه من الإيثانول إلى الإيثين."}]'::jsonb, '["السهم 2 ثم السهم 3","السهم 1 ثم السهم 3","السهم 1 ثم السهم 4","السهم 2 ثم السهم 4"]'::jsonb, 'تحليل', 'تمييز تفاعلات في مخطط تحويلات', 'صعب', 'الكتاب ص 185–187 — الحذف والإضافة'),
('mcq', 7, 'ما الأمر المشترك بين تفاعل حذف الهيدروجين وتفاعل حذف الماء؟', null, null, '["كلاهما يستهلك جزيئًا صغيرًا ويحول الرابطة الثنائية إلى أحادية","كلاهما يبدأ بمركب يحتوي على أكسجين وينتج ألكانًا مشبعًا","كلاهما يكوّن رابطة ثنائية بين ذرتي كربون متجاورتين وينتج جزيئًا صغيرًا","كلاهما يحتاج إلى عامل مؤكسد يكسب المركب العضوي أكسجينًا"]'::jsonb, 'فهم', 'مقارنة تفاعلين', 'متوسط', 'الكتاب ص 184–185 — تفاعلات الحذف'),
('essay', 1, 'أكمل المقارنة بين التفاعلات الأربعة الآتية: حذف الهيدروجين، وحذف الماء، وإضافة الماء، والهدرجة، من حيث: (1) نوع المركب المتفاعل، (2) الجزيء الصغير الذي يُضاف أو يُنتج، (3) نوع المركب الناتج.', null, null, null, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 185–187 — الحذف والإضافة'),
('essay', 2, 'اكتب معادلة موزونة بالصيغ البنائية المكثفة لكل من: (a) هدرجة البروبين، (b) حذف الهيدروجين من البروبان. ثم وضّح لماذا يُعد كل من التفاعلين عكس الآخر، وحدد نوع التفاعل العام (إضافة أو حذف) الذي ينتمي إليه كل منهما.', null, null, null, 'فهم', 'كتابة وتمييز', 'متوسط', 'الكتاب ص 185–187 — حذف الهيدروجين والهدرجة'),
('essay', 3, 'قال طالب: «حذف الماء وإضافة الماء تفاعل واحد؛ لأن الماء يظهر في كليهما». قوّم هذه العبارة، مستعينًا بمعادلتين للإيثانول والإيثين.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 185–186 — حذف الماء وإضافة الماء')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
