from (values
('mcq', 1, 2, 'تفاعلات حذف الهيدروجين تفاعلات حذف يصاحبها خروج ذرتي هيدروجين تكوّنان جزيء H₂، مثل تحول الإيثان إلى إيثين: CH₃–CH₃ → CH₂=CH₂ + H₂.', '["الهدرجة عكس ذلك: إضافة H₂ إلى الرابطة الثنائية لتحويل الألكين إلى ألكان.","في حذف الماء تُنزع ذرة H ومجموعة OH من كحول ويخرج H₂O لا H₂.","","إضافة الماء تكسر الرابطة الثنائية ولا تكوّنها، وتنتج كحولًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.708Z"}'::jsonb),
('mcq', 2, 0, 'المتفاعل كحول (الإيثانول) نُزعت منه ذرة H من ذرة كربون ومجموعة OH من ذرة الكربون المجاورة فتكونت رابطة ثنائية (إيثين) وخرج جزيء ماء؛ فهو تفاعل حذف الماء.', '["","إضافة الماء تسير في الاتجاه المعاكس: يتفاعل الألكين مع الماء ليكوّن كحولًا.","في حذف الهيدروجين يكون المتفاعل ألكانًا والجزيء الخارج H₂، أما هنا فالمتفاعل كحول والخارج H₂O.","الهدرجة إضافة H₂ إلى الرابطة الثنائية، وهنا تكونت رابطة ثنائية ولم يُضف شيء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-14T13:39:20.708Z"}'::jsonb),
('mcq', 3, 1, 'أُضيفت ذرة H من جزيء الماء إلى إحدى ذرتي الرابطة الثنائية وأُضيفت مجموعة OH إلى الذرة الأخرى، فتحولت الرابطة الثنائية إلى أحادية وتكوّن كحول؛ فهو تفاعل إضافة الماء.', '["حذف الماء يُنتج الماء من الكحول، أما هنا فالماء متفاعل يُستهلك.","","الهدرجة تضيف جزيء H₂ وتنتج ألكانًا، أما هنا فأُضيف H₂O ونتج كحول.","حذف الهيدروجين يكوّن رابطة ثنائية ويُخرج H₂، وهنا اختفت الرابطة الثنائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-14T13:39:20.708Z"}'::jsonb),
('mcq', 4, 3, 'في إضافة الماء تُضاف H وOH إلى الرابطة الثنائية فيتحول الألكين إلى كحول، وفي حذف الماء تُنزع H وOH من الكحول فيتحول إلى ألكين؛ فالمعادلة العامة لإضافة الماء عكس تفاعل حذف الماء.', '["كلاهما إضافة إلى ألكين، ولا يعكس أحدهما الآخر؛ فالأول يعطي ألكانًا والثاني كحولًا.","كلاهما حذف يكوّن رابطة ثنائية، فلا يكون أحدهما عكس الآخر.","عكس الهدرجة هو حذف الهيدروجين لا حذف الماء؛ فالهدرجة تُستهلك فيها H₂ وحذف الماء يُنتج H₂O.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.708Z"}'::jsonb),
('mcq', 5, 0, 'الهدرجة إضافة الهيدروجين إلى ذرات الكربون المكونة للرابطة الثنائية أو الثلاثية؛ فعند إضافة جزيء H₂ إلى الرابطة الثنائية يتحول الألكين إلى ألكان.', '["","هذا تحول حذف الهيدروجين، وهو عكس الهدرجة.","تحول الألكين إلى كحول يحدث بإضافة الماء لا الهيدروجين.","تحول الكحول إلى ألكين يحدث بحذف الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.708Z"}'::jsonb),
('mcq', 6, 1, 'السهم 1 يحول الإيثان إلى إيثين بنزع H₂ (حذف الهيدروجين)، والسهم 3 يحول الإيثين إلى إيثانول بإضافة H₂O (إضافة الماء). أما السهم 2 فهدرجة، والسهم 4 حذف الماء.', '["السهم 2 يحول الإيثين إلى إيثان بإضافة H₂، فهو هدرجة لا حذف هيدروجين.","","السهم 4 يحول الإيثانول إلى إيثين، فهو حذف الماء لا إضافته.","السهم 2 هدرجة والسهم 4 حذف الماء؛ فكلاهما عكس المطلوب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.709Z"}'::jsonb),
('mcq', 7, 2, 'في كل منهما تُنزع ذرتان (أو ذرة ومجموعة) من ذرتي كربون متجاورتين فتتكون رابطة ثنائية (ألكين)، ويخرج جزيء صغير مستقر: H₂ في حذف الهيدروجين، وH₂O في حذف الماء.', '["هذا وصف الإضافة (الهدرجة وإضافة الماء)، لا الحذف.","حذف الهيدروجين يبدأ بألكان لا يحتوي على أكسجين، وناتج النوعين ألكين غير مشبع لا ألكان.","","تفاعلات الحذف لا تحتاج إلى عامل مؤكسد، ولا يكتسب الناتج فيها أكسجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.709Z"}'::jsonb),
('essay', 1, null::int, null, null, 'حذف الهيدروجين: المتفاعل ألكان، يُنتج جزيء H₂، والناتج ألكين. حذف الماء: المتفاعل كحول، يُنتج جزيء H₂O، والناتج ألكين. إضافة الماء: المتفاعل ألكين، يُضاف إليه H₂O (H إلى ذرة كربون وOH إلى الأخرى)، والناتج كحول. الهدرجة: المتفاعل ألكين (أو ألكاين)، يُضاف إليه H₂، والناتج ألكان (أو ألكين من الألكاين بجزيء H₂ واحد).', '["حذف الهيدروجين: ألكان → ألكين + H₂","حذف الماء: كحول → ألكين + H₂O","إضافة الماء: ألكين + H₂O → كحول","الهدرجة: ألكين + H₂ → ألكان"]'::jsonb, '[]'::jsonb, '[{"element":"حذف الهيدروجين","marks":1},{"element":"حذف الماء","marks":1},{"element":"إضافة الماء","marks":1},{"element":"الهدرجة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الصفوف الأربعة صحيحة في عناصرها الثلاثة"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا: عنصران أو ثلاثة من عناصر الإجابة صحيحة"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الجزيء المضاف في الإضافة والجزيء الناتج في الحذف","القول إن حذف الماء ينتج ألكانًا","القول إن الهدرجة تنتج كحولًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.709Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) CH₂=CH–CH₃ + H₂ → CH₃–CH₂–CH₃. (b) CH₃–CH₂–CH₃ → CH₂=CH–CH₃ + H₂. في الهدرجة يُضاف جزيء H₂ إلى ذرتي الرابطة الثنائية فيتحول الألكين إلى ألكان، وفي حذف الهيدروجين تُنزع ذرتا H من ذرتين متجاورتين فيتحول الألكان إلى ألكين ويخرج H₂؛ فالمتفاعلات في أحدهما هي النواتج في الآخر. الهدرجة من تفاعلات الإضافة، وحذف الهيدروجين من تفاعلات الحذف.', '["معادلة هدرجة البروبين","معادلة حذف الهيدروجين من البروبان","تعليل العلاقة العكسية","تصنيف كل منهما (إضافة/حذف)"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة (a)","marks":1},{"element":"معادلة (b)","marks":1},{"element":"تعليل العلاقة العكسية","marks":1},{"element":"التصنيف","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"معادلتان صحيحتان موزونتان مع تعليل العلاقة وتصنيف صحيح"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا: عنصران أو ثلاثة من عناصر الإجابة صحيحة"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان H₂ في نواتج حذف الهيدروجين","تصنيف الهدرجة تفاعل حذف","كتابة ناتج الهدرجة بروباين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.709Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة. ظهور الماء في التفاعلين لا يجعلهما تفاعلًا واحدًا؛ ففي حذف الماء يكون الماء ناتجًا: يتحول الكحول إلى ألكين بنزع H وOH من ذرتي كربون متجاورتين وتكوين رابطة ثنائية: CH₃CH₂OH → CH₂=CH₂ + H₂O (تفاعل حذف). وفي إضافة الماء يكون الماء متفاعلًا: يُضاف H وOH إلى ذرتي الرابطة الثنائية فيتحول الألكين إلى كحول: CH₂=CH₂ + H₂O → CH₃CH₂OH (تفاعل إضافة). فهما تفاعلان متعاكسان من نوعين مختلفين.', '["الحكم: العبارة غير صحيحة","الماء ناتج في الحذف ومتفاعل في الإضافة","معادلة حذف الماء من الإيثانول","معادلة إضافة الماء إلى الإيثين مع بيان أنهما متعاكسان"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"دور الماء في كل تفاعل","marks":1},{"element":"معادلة حذف الماء","marks":1},{"element":"معادلة إضافة الماء والعلاقة العكسية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع تعليل مبني على دور الماء ومعادلتين صحيحتين"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا: عنصران أو ثلاثة من عناصر الإجابة صحيحة"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول العبارة لأن المادتين نفسيهما تظهران","عكس المتفاعل والناتج في إحدى المعادلتين","تصنيف التفاعلين كليهما إضافة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.709Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
