('mcq', 1, 'يمثل المخطط الآتي أكسدة كحول. ما الناتج العضوي لهذا التفاعل؟', null, '[{"src":"qimg/chem22/c5-l4-2-propanol-ox.svg","alt":"معادلة غير مكتملة: CH₃–CH–CH₃ وتتصل مجموعة OH إلى الأعلى بذرة الكربون الوسطى، أي CH₃CH(OH)CH₃ + (O) → علامة استفهام مكان الناتج. يمثل (O) الأكسجين القادم من عامل مؤكسد."}]'::jsonb, '["بروبانال","حمض البروبانويك","بروبين","2-بروبانون"]'::jsonb, 'تطبيق', 'تحديد ناتج أكسدة', 'سهل', 'الكتاب ص 188 — الجدول 5-13 (الحصول على الكيتونات)'),
('mcq', 2, 'في المخطط الآتي يتأكسد 1-بروبانول على خطوتين. ما المركبان A وB؟', null, '[{"src":"qimg/chem22/c5-l4-propanol-ab.svg","alt":"مخطط من اليسار إلى اليمين: 1-بروبانول CH₃–CH₂–CH₂–OH، ثم سهم مكتوب فوقه «أكسدة» يؤدي إلى المركب A، ثم سهم ثانٍ مكتوب فوقه «أكسدة» يؤدي من المركب A إلى المركب B."}]'::jsonb, '["A: بروبانال، B: حمض البروبانويك","A: 2-بروبانون، B: حمض البروبانويك","A: حمض البروبانويك، B: بروبانال","A: بروبانال، B: 2-بروبانون"]'::jsonb, 'تحليل', 'تحديد نواتج أكسدة متتالية', 'متوسط', 'الكتاب ص 188–189 — أكسدة 1-بروبانول'),
('mcq', 3, 'لماذا لا يُنتج 2-هكسانول CH₃CH(OH)CH₂CH₂CH₂CH₃ حمضًا كربوكسيليًّا عند أكسدته، كما يحدث عند أكسدة 1-هكسانول CH₃CH₂CH₂CH₂CH₂CH₂OH؟', null, null, '["لأنه لا يتأكسد أبدًا لعدم وجود ذرة هيدروجين على ذرة الكربون المرتبطة بمجموعة OH","لأن أكسدته تنتج ألكينًا بحذف الماء فلا يتكون أي مركب كربونيل","لأنه يتأكسد إلى كيتون، والكيتون لا يتأكسد بسهولة إلى حمض كربوكسيلي","لأنه يتأكسد إلى ألدهيد يتحول مباشرة إلى إستر لا إلى حمض"]'::jsonb, 'فهم', 'تفسير اختلاف نواتج الأكسدة', 'متوسط', 'الكتاب ص 189 — مقارنة أكسدة 1-بروبانول و2-بروبانول'),
('mcq', 4, 'أيّ الكحولات الآتية ينتج عن أكسدته كيتون؟', null, null, '["1-بنتانول","2-بنتانول","الإيثانول","الميثانول"]'::jsonb, 'تحليل', 'تحديد كحول من ناتج أكسدته', 'متوسط', 'الكتاب ص 188–189 — الجدول 5-13'),
('mcq', 5, 'عند استمرار أكسدة الميثانول خطوة بعد خطوة، ما المادة التي تنتج في الخطوة الأخيرة؟', null, null, '["ثاني أكسيد الكربون","الميثانال (الفورمالدهيد)","حمض الميثانويك (الفورميك)","الميثان والماء"]'::jsonb, 'فهم', 'تحديد ناتج أكسدة متتالية', 'سهل', 'الكتاب ص 188 — الجدول 5-13 (الحصول على الألدهيدات والأحماض الكربوكسيلية)'),
('mcq', 6, 'عند أكسدة الميثانول CH₃OH إلى ميثانال HCHO، ما الذي يحدث لجزيء الميثانول؟', null, null, '["يكتسب ذرة أكسجين","يفقد جزيء ماء فيتكون ألكين","يكتسب ذرتي هيدروجين","يفقد ذرتي هيدروجين"]'::jsonb, 'فهم', 'تفسير الأكسدة', 'صعب', 'الكتاب ص 188 — تفاعلات الأكسدة والاختزال (الجدول 5-13)'),
('mcq', 7, 'تمثل الصيغتان الآتيتان كحولين لهما الصيغة الجزيئية نفسها C₄H₁₀O. ما ناتج الخطوة الأولى لأكسدة كل منهما؟', null, '[{"src":"qimg/chem22/c5-l4-butanols.svg","alt":"صيغتان بنائيتان مكثفتان: المركب (1) إلى اليمين CH₃–CH₂–CH₂–CH₂–OH ومجموعة OH مرتبطة بذرة الكربون الطرفية؛ والمركب (2) إلى اليسار CH₃–CH₂–CH–CH₃ ومجموعة OH متصلة إلى الأعلى بمجموعة CH، أي بذرة كربون مرتبطة بذرتي كربون أخريين."}]'::jsonb, '["(1) 2-بيوتانون، (2) بيوتانال","(1) بيوتانال، (2) 2-بيوتانون","(1) بيوتانال، (2) حمض البيوتانويك","(1) حمض البيوتانويك، (2) بيوتانال"]'::jsonb, 'تحليل', 'مقارنة نواتج أكسدة متشكلين', 'صعب', 'الكتاب ص 188–189 — أكسدة الكحولات'),
('essay', 1, 'قارن بين أكسدة 1-بروبانول وأكسدة 2-بروبانول: اكتب معادلة كل خطوة أكسدة بالصيغ البنائية المكثفة مستعملًا (O) لتمثيل الأكسجين من العامل المؤكسد، وسمِّ كل ناتج، ثم فسّر سبب الاختلاف في النواتج.', null, null, null, 'تحليل', 'مقارنة وكتابة معادلات', 'متوسط', 'الكتاب ص 188–189 — الجدول 5-13'),
('essay', 2, 'يتأكسد الإيثانول CH₃CH₂OH على خطوتين. اكتب معادلة كل خطوة، وسمِّ الناتج العضوي في كل منهما، ثم بيّن لماذا تُعد كل خطوة أكسدة بالاعتماد على اكتساب الأكسجين أو فقد الهيدروجين.', null, null, null, 'تحليل', 'كتابة وتفسير', 'صعب', 'الكتاب ص 188 — تفاعلات الأكسدة والاختزال'),
('essay', 3, 'أراد طالب تحضير حمض البروبانويك بأكسدة كحول، وكان لديه 1-بروبانول و2-بروبانول.
(a) أي الكحولين يجب أن يختار؟ علل إجابتك.
(b) لماذا يُعد تحضير الألدهيد بأكسدة الكحول من المهام الصعبة؟', null, null, null, 'تقويم', 'اختيار وتعليل', 'سهل', 'الكتاب ص 188–189 — أكسدة الكحولات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
