('mcq', 4, 'ما نوع التفاعل العضوي اللازم لتحويل هاليد الألكيل إلى ألكين، مع تحرر هاليد الهيدروجين HX؟', null, null, '["تفاعل استبدال","تفاعل إضافة","تفاعل حذف","تفاعل أكسدة واختزال"]'::jsonb, 'تحليل', 'تحديد التفاعل اللازم لتحويل', 'متوسط', 'الكتاب ص 185 — الحذف، وص 203 (س48c)'),
('mcq', 5, 'ما التفاعل العضوي الأنسب لتحويل ألكين إلى كحول؟', null, null, '["تفاعل حذف الماء","تفاعل إضافة الماء","تفاعل الهدرجة","استبدال بمجموعة OH"]'::jsonb, 'تحليل', 'تحديد التفاعل اللازم لتحويل', 'متوسط', 'الكتاب ص 186 — إضافة الماء، وص 203 (س48f)'),
('mcq', 6, 'يمثل المخطط الآتي تحويل الإيثانول إلى الإيثانال. ما نوع التفاعل اللازم مكان علامة الاستفهام؟', null, '[{"src":"qimg/chem22/c5-l4-ethanol-ethanal.svg","alt":"مخطط من اليسار إلى اليمين: إيثانول CH₃–CH₂–OH، ثم سهم فوقه علامة استفهام، ثم إيثانال CH₃–C(=O)–H (ذرة كربون مرتبطة بمجموعة CH₃ وبذرة أكسجين برابطة ثنائية وبذرة هيدروجين)."}]'::jsonb, '["تفاعل أكسدة واختزال","تفاعل إضافة الماء","تفاعل استبدال","تفاعل تكثف"]'::jsonb, 'تحليل', 'تحديد التفاعل اللازم لتحويل', 'متوسط', 'الكتاب ص 188 (الجدول 5-13) وص 203 (س51d)'),
('mcq', 7, 'يُراد تحويل 1-برومو بروبان CH₃CH₂CH₂Br إلى بروبانال CH₃CH₂CHO على خطوتين. ما التسلسل الصحيح لنوعي التفاعلين؟', null, null, '["حذف ثم أكسدة","استبدال ثم حذف","إضافة ثم أكسدة","استبدال ثم أكسدة"]'::jsonb, 'تحليل', 'تخطيط تحويل على خطوتين', 'صعب', 'الكتاب ص 172 و188 — الاستبدال وأكسدة الكحولات'),
('essay', 1, 'اكتب اسم التفاعل العضوي اللازم لإجراء كل تحويل مما يأتي، مع معادلة عامة توضحه:
