from (values
('mcq', 1, 'لماذا تُستعمل المحفزات عادةً في عملية هدرجة الألكينات والزيوت النباتية؟', null, null, '["لأنها تزيد كمية الهيدروجين المتاحة للتفاعل","لأن طاقة تنشيط التفاعل عالية جدًّا دون محفز","لأنها تجعل تفاعل الهدرجة ماصًّا للحرارة","لأنها تتحد مع الزيت فتكوّن الدهن الصلب"]'::jsonb, 'فهم', 'تفسير استعمال المحفز', 'سهل', 'الكتاب ص 187 — هدرجة الألكينات'),
('mcq', 2, 'أيّ مما يأتي يُستعمل محفزًا في هدرجة الزيوت النباتية؟', null, null, '["أكسيد النحاس II وثاني كرومات البوتاسيوم","حمض الكبريتيك المركز وبورات الصوديوم","مسحوق البلاتين أو مسحوق البلاديوم","فلزا الصوديوم والبوتاسيوم النشطان"]'::jsonb, 'تذكر', 'تعرف محفزات', 'سهل', 'الكتاب ص 187 — المحفزات في الهدرجة'),
('mcq', 3, 'كيف يعمل المحفز على تسريع هدرجة الزيوت النباتية؟', null, null, '["يوفر سطحًا تُدمص عليه جزيئات المتفاعلات فتتهيأ إلكتروناتها للارتباط بذرات أخرى","يتفاعل مع الزيت ويصبح جزءًا من جزيء الدهن المشبع الناتج من التفاعل","يرفع طاقة جزيئات المتفاعلات فوق قمة منحنى الطاقة دون تغيير مسار التفاعل","يؤكسد الروابط الثنائية في الزيت إلى مجموعات كربونيل يسهل تفاعلها"]'::jsonb, 'فهم', 'تفسير آلية عمل المحفز', 'متوسط', 'الكتاب ص 187 — المحفزات في الهدرجة'),
('mcq', 4, 'ما الذي ينتج عن هدرجة الزيوت النباتية مثل زيت فول الصويا والذرة؟', null, null, '["سوائل دهنية غير مشبعة أكثر سيولة من الزيت","أحماض كربوكسيلية قصيرة السلسلة ذائبة في الماء","كحولات ناتجة عن إضافة الماء إلى الزيت","دهون مشبعة صلبة عند درجة حرارة الغرفة كالسمن"]'::jsonb, 'فهم', 'تحديد ناتج الهدرجة', 'سهل', 'الكتاب ص 187 — هدرجة الزيوت النباتية'),
('mcq', 5, 'ما التغير الذي يحدث في الروابط بين ذرات الكربون في جزيئات الزيت النباتي عند هدرجتها بوجود محفز؟', null, null, '["تتحول الروابط الأحادية C–C إلى روابط ثنائية C=C","تُستبدل ذرات الهيدروجين المرتبطة بالكربون بذرات المحفز","تتحول الروابط الثنائية C=C إلى روابط أحادية C–C","تنكسر السلسلة الكربونية الطويلة إلى جزيئات أصغر"]'::jsonb, 'فهم', 'تفسير التغير في الروابط', 'متوسط', 'الكتاب ص 186–187 — الهدرجة'),
('mcq', 6, 'يمثل المخطط الآتي منحنيي الطاقة لهدرجة زيت نباتي بوجود محفز ودونه. أيّ المنحنيين يمثل التفاعل بوجود المحفز؟ ولماذا؟', null, '[{"src":"qimg/chem22/c5-l4-cat-profile.svg","alt":"مخطط طاقة: المحور الرأسي «الطاقة الكامنة» والمحور الأفقي «سير التفاعل». يبدأ منحنيان من مستوى المتفاعلات نفسه (زيت + H₂) وينتهيان عند مستوى النواتج نفسه (دهن مشبع) الذي يقع أدنى من مستوى المتفاعلات. المنحنى (1) خط أحمر متقطع قمته مرتفعة جدًّا، والمنحنى (2) خط أزرق متصل قمته أقل ارتفاعًا بكثير من قمة المنحنى (1)."}]'::jsonb, '["المنحنى (1)؛ لأن طاقة تنشيطه أكبر فتصطدم الجزيئات بطاقة أعلى","المنحنى (2)؛ لأن المحفز يخفض طاقة التنشيط اللازمة لحدوث التفاعل","المنحنى (2)؛ لأن المحفز يجعل طاقة النواتج أدنى فيزيد الحرارة المنطلقة","المنحنى (1)؛ لأن المحفز يرفع طاقة المتفاعلات فيسرع التفاعل"]'::jsonb, 'تحليل', 'تفسير مخطط طاقة', 'متوسط', 'الكتاب ص 184 و187 — المحفز وطاقة التنشيط في الهدرجة'),
('mcq', 7, 'يحتوي جزيء حمض دهني في زيت نباتي على رابطتين ثنائيتين C=C. كم جزيئًا من H₂ يلزم لتحويله إلى حمض دهني مشبع تمامًا؟', null, null, '["جزيء واحد","ثلاثة جزيئات","جزيئان","أربعة جزيئات"]'::jsonb, 'تطبيق', 'حساب عدد جزيئات H₂', 'صعب', 'الكتاب ص 186–187 — الهدرجة'),
('essay', 1, 'فسّر استعمال المحفزات في هدرجة الزيوت النباتية، متناولًا: (1) سبب الحاجة إليها، (2) أمثلة عليها، (3) كيفية عملها، (4) الناتج الصناعي لهذه العملية.', null, null, null, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 187 — المحفزات في الهدرجة'),
('essay', 2, 'يمثل المخطط الآتي منحنيي الطاقة لهدرجة زيت نباتي بوجود محفز ودونه.
(a) حدد المنحنى الذي يمثل التفاعل بوجود المحفز، وعلل.
(b) هل يختلف التغير في المحتوى الحراري ΔH بين المنحنيين؟ فسّر من المخطط.
(c) فسّر لماذا يكون تفاعل الهدرجة دون محفز بطيئًا جدًّا.', null, '[{"src":"qimg/chem22/c5-l4-cat-profile.svg","alt":"مخطط طاقة: المحور الرأسي «الطاقة الكامنة» والمحور الأفقي «سير التفاعل». يبدأ منحنيان من مستوى المتفاعلات نفسه (زيت + H₂) وينتهيان عند مستوى النواتج نفسه (دهن مشبع) الذي يقع أدنى من مستوى المتفاعلات. المنحنى (1) خط أحمر متقطع قمته مرتفعة جدًّا، والمنحنى (2) خط أزرق متصل قمته أقل ارتفاعًا بكثير من قمة المنحنى (1)."}]'::jsonb, null, 'تحليل', 'تفسير مخطط طاقة', 'متوسط', 'الكتاب ص 184 و187 — المحفز وطاقة التنشيط'),
('essay', 3, 'في مصنع لإنتاج السمن من زيت الذرة يُستعمل المحفز الفلزي على شكل مسحوق ناعم لا على شكل قطعة واحدة.
(a) فسّر لماذا يُفضَّل المسحوق الناعم.
(b) إذا احتوى جزيء من الزيت على ثلاث روابط ثنائية C=C، فكم جزيئًا من H₂ يلزم لتشبيعه تمامًا؟ علّل.
(c) هل يلزم المصنع إضافة كمية جديدة من البلاديوم مساوية لكمية الزيت في كل دفعة؟ فسّر.', null, null, null, 'تحليل', 'تطبيق وتفسير', 'صعب', 'الكتاب ص 184 و187 — المحفز وهدرجة الزيوت')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C5-L4-O07') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'طاقة تنشيط تفاعل الهدرجة عالية جدًّا في غياب المحفز، فيكون التفاعل بطيئًا جدًّا؛ والمحفز مادة تزيد سرعة التفاعل بخفض طاقة التنشيط دون أن تُستهلك.', '["المحفز لا يغير كمية المتفاعلات، بل يخفض طاقة التنشيط.","","المحفز لا يغير ΔH للتفاعل ولا يحوله من طارد إلى ماص للحرارة.","المحفز لا يُستهلك ولا يصبح جزءًا من الناتج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.713Z"}'::jsonb),
('mcq', 2, 2, 'من المحفزات المستعملة في الهدرجة مسحوق البلاتين أو البلاديوم؛ إذ يوفر سطحًا تُدمص عليه جزيئات المتفاعلات.', '["هذه عوامل مؤكسدة تُستعمل مصدرًا للأكسجين في تفاعلات الأكسدة، لا محفزات للهدرجة.","حمض الكبريتيك المركز يُستعمل في تحضير الإستر، وبورات الصوديوم ليست من محفزات الهدرجة؛ فمحفزات الهدرجة فلزات مثل البلاتين والبلاديوم.","","الصوديوم والبوتاسيوم فلزان نشطان يتفاعلان ولا يُستعملان محفزًا لإضافة الهيدروجين إلى الزيوت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-14T13:39:20.713Z"}'::jsonb),
('mcq', 3, 0, 'المحفز مثل مسحوق البلاتين أو البلاديوم يوفر سطحًا يعمل على ادمصاص جزيئات المواد المتفاعلة، ويهيئ الفرصة للإلكترونات للارتباط مع ذرات أخرى، فيتم التفاعل بطاقة تنشيط أقل.', '["","المحفز لا يُستهلك ولا يدخل في تركيب الناتج.","المحفز لا يرفع طاقة المتفاعلات، بل يوفر مسارًا بطاقة تنشيط أقل.","الهدرجة إضافة هيدروجين لا أكسدة، والمحفز لا يكوّن مجموعات كربونيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-14T13:39:20.713Z"}'::jsonb),
('mcq', 4, 3, 'تحول الهدرجة السوائل الدهنية غير المشبعة في الزيوت النباتية إلى دهون مشبعة صلبة عند درجة حرارة الغرفة، وتُستعمل الدهون المهدرجة في صناعة السمن.', '["الهدرجة تقلل عدم التشبع، فيصبح الناتج أكثر صلابة لا أكثر سيولة.","الهدرجة لا تكسر السلسلة ولا تكوّن أحماضًا كربوكسيلية.","تكوين الكحولات يحتاج إلى إضافة الماء، والهدرجة تضيف الهيدروجين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-14T13:39:20.713Z"}'::jsonb),
('mcq', 5, 2, 'يُضاف جزيء H₂ إلى كل رابطة ثنائية C=C فتتحول إلى رابطة أحادية، فيصبح الحمض الدهني مشبعًا.', '["هذا عكس الهدرجة، أي حذف الهيدروجين.","المحفز لا يرتبط بالناتج ولا يحل محل الهيدروجين؛ فالتفاعل إضافة لا استبدال.","","الهدرجة لا تكسر السلسلة الكربونية بل تضيف الهيدروجين إلى روابطها الثنائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.713Z"}'::jsonb),
('mcq', 6, 1, 'المنحنيان يبدآن وينتهيان عند المستويات نفسها، ويختلفان في ارتفاع القمة فقط؛ والمحفز يخفض طاقة التنشيط، فالمنحنى (2) ذو القمة الأقل يمثل التفاعل بوجود المحفز.', '["طاقة التنشيط الأكبر تعني تفاعلًا أبطأ، وهذه صفة التفاعل دون محفز.","","مستوى النواتج واحد في المنحنيين؛ فالمحفز لا يغير ΔH.","مستوى المتفاعلات واحد في المنحنيين؛ والمحفز لا يرفع طاقتها بل يخفض قمة المنحنى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-14T13:39:20.713Z"}'::jsonb),
('mcq', 7, 2, 'يتفاعل جزيء واحد من H₂ مع كل رابطة ثنائية بشكل تام؛ فلرابطتين ثنائيتين يلزم جزيئان من H₂.', '["جزيء واحد يشبع رابطة ثنائية واحدة فقط وتبقى الأخرى.","ثلاثة جزيئات تلزم لثلاث روابط ثنائية لا لرابطتين.","","أربعة جزيئات تعني عد ذرات الهيدروجين المضافة (4 ذرات) بدل عد الجزيئات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.714Z"}'::jsonb),
('essay', 1, null::int, null, null, '(1) طاقة تنشيط تفاعل الهدرجة عالية جدًّا في غياب المحفز فيكون التفاعل بطيئًا جدًّا. (2) مسحوق البلاتين أو البلاديوم. (3) يوفر المحفز سطحًا يعمل على ادمصاص جزيئات المواد المتفاعلة (الزيت والهيدروجين)، ويهيئ الفرصة للإلكترونات للارتباط مع ذرات أخرى، فيتم التفاعل بطاقة تنشيط أقل دون أن يُستهلك المحفز. (4) تتحول السوائل الدهنية غير المشبعة في الزيوت (فول الصويا، الذرة، الفول السوداني) إلى دهون مشبعة صلبة عند درجة حرارة الغرفة تُستعمل في صناعة السمن.', '["طاقة التنشيط عالية دون محفز","البلاتين أو البلاديوم","ادمصاص الجزيئات على سطح المحفز","تحويل الزيوت إلى دهون صلبة (السمن)"]'::jsonb, '[]'::jsonb, '[{"element":"سبب الحاجة","marks":1},{"element":"الأمثلة","marks":1},{"element":"آلية العمل","marks":1},{"element":"الناتج الصناعي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل يشمل العناصر الأربعة"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا: عنصران أو ثلاثة من عناصر الإجابة صحيحة"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المحفز يُستهلك في التفاعل","ذكر عوامل مؤكسدة مثل ثاني كرومات البوتاسيوم محفزات للهدرجة","القول إن الهدرجة تجعل الزيت أكثر سيولة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.714Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) المنحنى (2)؛ لأن قمته أقل ارتفاعًا، أي أن طاقة التنشيط فيه أقل، والمحفز يخفض طاقة التنشيط. (b) لا يختلف؛ فالمنحنيان يبدآن من مستوى المتفاعلات نفسه وينتهيان عند مستوى النواتج نفسه، فالفرق بينهما (ΔH، وهو سالب لأن النواتج أدنى طاقة) واحد، والمحفز لا يغير ΔH. (c) لأن طاقة تنشيط التفاعل دون محفز (المنحنى 1) عالية جدًّا، فلا تمتلك إلا نسبة ضئيلة من الجزيئات المتصادمة الطاقة اللازمة لتكوين المعقد المنشط، فتقل التصادمات الفعالة ويكون التفاعل بطيئًا جدًّا.', '["المنحنى (2) مع التعليل بطاقة التنشيط","ΔH لا يتغير لتساوي مستويي المتفاعلات والنواتج","طاقة التنشيط العالية تعني قلة التصادمات الفعالة"]'::jsonb, '[]'::jsonb, '[{"element":"(a)","marks":1},{"element":"(b)","marks":1},{"element":"(c)","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الإجابات الثلاث صحيحة مع تعليل مبني على المخطط"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار المنحنى (1) لأن قمته أعلى","القول إن المحفز يجعل التفاعل أكثر إطلاقًا للحرارة","الخلط بين طاقة التنشيط وΔH"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-14T13:39:20.714Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) لأن المحفز يعمل من خلال سطحه الذي تُدمص عليه جزيئات المتفاعلات؛ والمسحوق الناعم مساحة سطحه أكبر بكثير من القطعة الواحدة، فيوفر مواقع أكثر للادمصاص فيزداد معدل التفاعل. (b) ثلاثة جزيئات من H₂؛ لأن جزيء H₂ واحدًا يُضاف إلى كل رابطة ثنائية فيحولها إلى أحادية. (c) لا؛ لأن المحفز يزيد سرعة التفاعل دون أن يُستهلك فيه، فيمكن استعمال الكمية نفسها مرات عديدة ولا يرتبط مقداره بكمية الزيت.', '["مساحة سطح أكبر تعني ادمصاصًا أكثر","3 جزيئات H₂ مع التعليل","المحفز لا يُستهلك"]'::jsonb, '[]'::jsonb, '[{"element":"(a)","marks":1},{"element":"(b)","marks":1},{"element":"(c)","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الإجابات الثلاث صحيحة ومعللة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المسحوق يذوب في الزيت فيتفاعل معه","الإجابة بستة جزيئات (عد ذرات H)","القول إن المحفز يُستهلك مثل المتفاعلات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.714Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C5-L4-O07') and x.type = v.type and x.number = v.number
