insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C5-L5-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما التعريف الصحيح للبوليمرات؟', null, null, '["جزيئات صغيرة تتفاعل معًا لتكوين المركبات العضوية","جزيئات كبيرة تتكوّن من العديد من الوحدات البنائية المتكررة","مخاليط من مركبات عضوية مختلفة لا ترتبط ببعضها","مركبات أيونية بلورية ذات درجات انصهار مرتفعة"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 191 — البوليمرات (التعريف)'),
('mcq', 2, 'في الصيغة الآتية لبوليمر البولي إيثيلين، علامَ يدل الحرف n؟', null, '[{"src":"qimg/chem22/c5-l5a-pe.svg","alt":"وحدة بنائية متكررة بين قوسين مربعين: مجموعة CH₂ مرتبطة برابطة أحادية بمجموعة CH₂ أخرى، وتعبر القوسين رابطتان طرفيتان، وأسفل القوس الأيمن الحرف n."}]'::jsonb, '["عدد الوحدات البنائية المتكررة في سلسلة البوليمر","عدد ذرات الكربون في الوحدة البنائية الواحدة","عدد جزيئات البوليمر الموجودة في العينة","عدد الروابط الثنائية في جزيء البوليمر"]'::jsonb, 'فهم', 'تفسير رمز في صيغة', 'سهل', 'الكتاب ص 191 — البوليمرات (التعريف)'),
('mcq', 3, 'ما المدى التقريبي للكتل المولية للبوليمرات الصناعية؟', null, null, '["من 16 amu إلى 100 amu تقريبًا","من 100 amu إلى 1000 amu تقريبًا","من أقل من 10,000 amu إلى أكثر من 1,000,000 amu","قيمة ثابتة تساوي 40,000 amu لجميع البوليمرات"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'متوسط', 'الكتاب ص 191 — البوليمرات (التعريف)'),
('mcq', 4, 'تحتوي سلسلة من بوليمر الطلاء غير اللاصق على نحو 400 وحدة بنائية، وكتلتها المولية 40,000 amu تقريبًا. ما الكتلة التقريبية للوحدة البنائية الواحدة؟', null, null, '["16,000,000 amu","0.01 amu","40,400 amu","100 amu"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 191 — البوليمرات (التعريف)'),
('mcq', 5, 'يمثّل الشكل الآتي جزيئات صغيرة متماثلة ترتبط معًا لتكوّن ناتجًا. ما الوصف الأدق للناتج؟', null, '[{"src":"qimg/chem22/c5-l5a-beads.svg","alt":"على يسار الشكل اثنتا عشرة كرة حمراء صغيرة متماثلة منفصلة بعضها عن بعض، يليها سهم يشير إلى اليمين، وعلى يمين السهم كرات حمراء متماثلة من النوع نفسه متصلة معًا بخط واحد في سلسلة طويلة منثنية."}]'::jsonb, '["مخلوط من جزيئات صغيرة منفصلة متماثلة","جزيء بوليمر كبير مكوّن من وحدات بنائية متكررة","بلورة أيونية تتكرر فيها الأيونات نفسها","جزيء صغير ناتج عن تفكك الجزيئات"]'::jsonb, 'فهم', 'تفسير نموذج', 'سهل', 'الكتاب ص 191 — البوليمرات (التعريف)'),
('mcq', 6, 'أيّ مما يأتي يُعدّ بوليمرًا طبيعيًّا معالَجًا كيميائيًّا؟', null, null, '["البولي إيثيلين","النايلون","السيليلويد","الإيثين"]'::jsonb, 'تذكر', 'تصنيف', 'متوسط', 'الكتاب ص 191 — البوليمرات (التعريف)'),
('mcq', 7, 'عينة من البولي إيثيلين كتلتها المولية 56,100 amu تقريبًا، وكتلة الوحدة البنائية (C₂H₄) فيها 28.05 amu. ما القيمة التقريبية لـ n في صيغته الآتية؟', null, '[{"src":"qimg/chem22/c5-l5a-pe.svg","alt":"وحدة بنائية متكررة بين قوسين مربعين: مجموعة CH₂ مرتبطة برابطة أحادية بمجموعة CH₂ أخرى، وتعبر القوسين رابطتان طرفيتان، وأسفل القوس الأيمن الحرف n."}]'::jsonb, '["2000","1,573,605","0.0005","4000"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 191 — البوليمرات (التعريف)'),
('essay', 1, 'عرّف البوليمرات، ثم فسّر لماذا تختلف الكتل المولية للبوليمرات اختلافًا كبيرًا من بوليمر إلى آخر، واذكر المدى التقريبي لهذه الكتل.', null, null, null, 'فهم', 'تعريف وتفسير', 'متوسط', 'الكتاب ص 191 — البوليمرات (التعريف)'),
('essay', 2, 'يبيّن الشكل الآتي الوحدة البنائية المتكررة للبولي إيثيلين (C₂H₄)، وكتلتها 28.05 amu. (أ) احسب الكتلة المولية لسلسلة تحتوي على 1000 وحدة بنائية. (ب) احسب عدد الوحدات البنائية n في سلسلة كتلتها المولية 140,250 amu. (ج) هل تقع الكتلتان ضمن المدى المعروف للكتل المولية للبوليمرات؟ وضّح.', null, '[{"src":"qimg/chem22/c5-l5a-pe.svg","alt":"وحدة بنائية متكررة بين قوسين مربعين: مجموعة CH₂ مرتبطة برابطة أحادية بمجموعة CH₂ أخرى، وتعبر القوسين رابطتان طرفيتان، وأسفل القوس الأيمن الحرف n."}]'::jsonb, null, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 191 — البوليمرات (التعريف)'),
('essay', 3, 'قديمًا اقتصر الناس على استعمال المواد الطبيعية. (أ) اذكر ثلاثًا من هذه المواد. (ب) وضّح الفرق بين البوليمرات الطبيعية المعالجة كيميائيًّا والبوليمرات الصناعية، مع مثال لكل منهما. (ج) ما أول بوليمر صناعي، ومتى حُضّر؟ (د) لماذا يُسمّى هذا العصر عصر البوليمرات؟', null, null, null, 'فهم', 'مقارنة وتفسير', 'صعب', 'الكتاب ص 191 — البوليمرات (التعريف)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C5-L5-O01') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'البوليمرات جزيئات كبيرة تتكوّن من العديد من الوحدات البنائية المتكررة المرتبطة معًا في سلاسل طويلة.', '["هذا وصف للمونومرات، وهي الجزيئات الصغيرة التي يُصنع منها البوليمر، لا البوليمر نفسه.","","البوليمر جزيء واحد كبير ترتبط وحداته معًا بروابط، وليس مخلوطًا من مركبات منفصلة.","البوليمرات جزيئات عضوية كبيرة، وليست مركبات أيونية بلورية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.715Z"}'::jsonb),
('mcq', 2, 0, 'يُكتب الرمز n بجانب الوحدة البنائية المحصورة بين القوسين ليشير إلى عدد الوحدات البنائية المتكررة في سلسلة البوليمر، وقيمته كبيرة وتختلف من بوليمر إلى آخر.', '["","عدد ذرات الكربون في الوحدة الظاهرة بين القوسين اثنتان، وهو ثابت ولا يُرمز إليه بـ n.","الرمز n يصف جزيء بوليمر واحد (طول سلسلته)، لا عدد الجزيئات في العينة.","لا توجد روابط ثنائية في الوحدة البنائية للبولي إيثيلين؛ فجميع الروابط بين ذرات الكربون أحادية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.715Z"}'::jsonb),
('mcq', 3, 2, 'لأن قيم n تختلف اختلافًا كبيرًا من بوليمر إلى آخر، فإن الكتل المولية للبوليمرات قد تكون أقل من 10,000 amu وقد تصل إلى أكثر من 1,000,000 amu.', '["هذه كتل مولية لجزيئات صغيرة كالميثان والهبتان، لا لجزيئات البوليمرات الضخمة.","هذه كتل مولية لجزيئات صغيرة أو متوسطة، وهي أقل كثيرًا من كتل البوليمرات.","","الكتلة المولية للبوليمرات غير ثابتة لأنها تعتمد على عدد الوحدات n؛ و40,000 amu مثال لبوليمر واحد فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-14T13:39:20.715Z"}'::jsonb),
('mcq', 4, 3, 'كتلة الوحدة البنائية = الكتلة المولية للسلسلة ÷ عدد الوحدات = 40,000 amu ÷ 400 = 100 amu.', '["ضُربت الكتلة المولية في عدد الوحدات بدل القسمة عليه.","قُسم عدد الوحدات على الكتلة المولية (قسمة مقلوبة).","جُمع عدد الوحدات إلى الكتلة المولية، ولا معنى لذلك.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.715Z"}'::jsonb),
('mcq', 5, 1, 'ترتبط الجزيئات الصغيرة المتماثلة (المونومرات) معًا في سلسلة طويلة واحدة، فيتكوّن جزيء كبير هو البوليمر، وتتكرر فيه الوحدات البنائية.', '["الجزيئات في الناتج مرتبطة معًا في سلسلة واحدة، وليست منفصلة كما في المخلوط.","","الشكل يمثل ترابط جزيئات في سلسلة، لا ترتيب أيونات في بلورة.","الناتج أكبر كثيرًا من الجزيئات المتفاعلة؛ فهو ناتج ترابط لا تفكك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-14T13:39:20.715Z"}'::jsonb),
('mcq', 6, 2, 'السيليلويد من البوليمرات الطبيعية المعالجة كيميائيًّا؛ إذ يُحضَّر بمعالجة سليلوز القطن أو الألياف الخشبية مع حمض النيتريك، وقد أصبح متاحًا للاستعمال قبل تطوير البوليمرات الصناعية.', '["البولي إيثيلين بوليمر صناعي يُحضَّر ببلمرة الإيثين.","النايلون بوليمر صناعي يُحضَّر بالبلمرة بالتكثف.","","الإيثين جزيء صغير (مونومر) وليس بوليمرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-14T13:39:20.715Z"}'::jsonb),
('mcq', 7, 0, 'n = الكتلة المولية للبوليمر ÷ كتلة الوحدة البنائية = 56,100 amu ÷ 28.05 amu = 2000 وحدة تقريبًا.', '["","ضُربت الكتلة المولية في كتلة الوحدة بدل القسمة عليها.","قُسمت كتلة الوحدة على الكتلة المولية (قسمة مقلوبة).","استُعملت كتلة المجموعة CH₂ (14.03 amu) بدل كتلة الوحدة البنائية كاملة (C₂H₄)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.715Z"}'::jsonb),
('essay', 1, null::int, null, null, 'البوليمرات جزيئات كبيرة تتكوّن من العديد من الوحدات البنائية المتكررة. ويُرمز إلى عدد الوحدات البنائية في السلسلة بالرمز n، ولأن قيم n تختلف اختلافًا كبيرًا من بوليمر إلى آخر تختلف الكتل المولية كثيرًا؛ فقد تكون أقل من 10,000 amu وقد تصل إلى أكثر من 1,000,000 amu.', '["البوليمر جزيء كبير","يتكوّن من العديد من الوحدات البنائية المتكررة","n عدد الوحدات البنائية ويختلف كثيرًا من بوليمر إلى آخر","الكتلة المولية تعتمد على n فتختلف تبعًا له","المدى: من أقل من 10,000 amu إلى أكثر من 1,000,000 amu"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف البوليمر جزيئًا كبيرًا","marks":1},{"element":"ذكر الوحدات البنائية المتكررة","marks":1},{"element":"بيان أن n عدد الوحدات ويختلف كثيرًا","marks":1},{"element":"ربط اختلاف الكتلة المولية باختلاف n","marks":1},{"element":"ذكر المدى التقريبي للكتل المولية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"3–4 درجات","description":"تعريف صحيح مع تفسير جزئي أو دون ذكر المدى"},{"level":"1–2 درجة","description":"تعريف ناقص دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف البوليمر بأنه جزيء صغير يتكرر","تفسير اختلاف الكتل باختلاف نوع الذرات فقط دون ذكر عدد الوحدات","ذكر مدى كتل الجزيئات الصغيرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-14T13:39:20.716Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) الكتلة المولية = n × كتلة الوحدة = 1000 × 28.05 amu = 28,050 amu. (ب) n = 140,250 amu ÷ 28.05 amu = 5000 وحدة. (ج) نعم؛ لأن الكتل المولية للبوليمرات تتراوح من أقل من 10,000 amu إلى أكثر من 1,000,000 amu، والقيمتان 28,050 amu و140,250 amu تقعان ضمن هذا المدى.', '["الكتلة المولية = 28,050 amu","n = 5000","القيمتان ضمن المدى من أقل من 10,000 amu إلى أكثر من 1,000,000 amu"]'::jsonb, '["الكتلة المولية = عدد الوحدات × كتلة الوحدة","1000 × 28.05 amu = 28,050 amu","n = الكتلة المولية ÷ كتلة الوحدة","n = 140,250 amu ÷ 28.05 amu = 5000","مقارنة القيمتين بالمدى المعروف للكتل المولية للبوليمرات"]'::jsonb, '[{"element":"حساب الكتلة المولية للسلسلة (أ)","marks":2},{"element":"حساب n (ب)","marks":2},{"element":"المقارنة بالمدى مع التوضيح (ج)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"3–4 درجات","description":"حساب أحد الجزأين صحيحًا مع خطأ في الآخر أو غياب التوضيح"},{"level":"1–2 درجة","description":"كتابة العلاقة الصحيحة دون إتمام الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة 1000 على 28.05 بدل الضرب في الجزء (أ)","ضرب 140,250 في 28.05 بدل القسمة في الجزء (ب)","استعمال كتلة CH₂ وحدها (14.03 amu) بدل كتلة الوحدة C₂H₄"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.716Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الحجر، والخشب، والمعادن، والصوف، والقطن (أي ثلاث منها). (ب) البوليمرات الطبيعية المعالجة كيميائيًّا مصدرها بوليمر طبيعي عولج كيميائيًّا، مثل المطاط والسيليلويد الذي يُحضَّر بمعالجة سليلوز القطن أو الألياف الخشبية مع حمض النيتريك؛ أما البوليمرات الصناعية فتُصنع بترابط مونومرات صغيرة، مثل البولي إيثيلين والنايلون. (ج) الباكالايت، حُضّر عام 1909م. (د) لأنه منذ عام 1909م طُوّرت مئات البوليمرات الصناعية، وانتشر استعمالها انتشارًا واسعًا في كل مجالات الحياة.', '["ثلاث مواد طبيعية","الطبيعية المعالجة: بوليمر طبيعي عولج كيميائيًّا مع مثال","الصناعية: تُصنع من مونومرات مع مثال","الباكالايت عام 1909م","تطوير مئات البوليمرات وانتشار استعمالها"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر ثلاث مواد طبيعية","marks":1},{"element":"وصف البوليمرات الطبيعية المعالجة مع مثال","marks":1},{"element":"وصف البوليمرات الصناعية مع مثال","marks":1},{"element":"الباكالايت وسنة تحضيره","marks":1},{"element":"تفسير تسمية عصر البوليمرات","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"3–4 درجات","description":"إجابة صحيحة لمعظم الأجزاء مع نقص في التوضيح أو الأمثلة"},{"level":"1–2 درجة","description":"ذكر المواد الطبيعية أو أول بوليمر صناعي فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ السيليلويد بوليمرًا صناعيًّا بالكامل","ذكر النايلون على أنه أول بوليمر صناعي","الخلط بين المواد الطبيعية والبوليمرات الصناعية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-14T13:39:20.716Z"}'::jsonb)
