('mcq', 5, 'في معادلة البلمرة الآتية، ماذا يُسمّى الجزيء CH₂=CH₂؟', null, '[{"src":"qimg/chem22/c5-l5a-ethene-pe.svg","alt":"معادلة: n CH₂=CH₂ (رابطة ثنائية بين مجموعتي CH₂)، ثم سهم يشير إلى اليمين، ثم وحدة بنائية بين قوسين مربعين: مجموعة CH₂ مرتبطة برابطة أحادية بمجموعة CH₂، وتعبر القوسين رابطتان طرفيتان، وأسفل القوس الأيمن الحرف n."}]'::jsonb, '["البوليمر الناتج","الوحدة البنائية المتكررة","الحفّاز في التفاعل","المونومر المتفاعل"]'::jsonb, 'تذكر', 'تمييز المصطلح', 'سهل', 'الكتاب ص 192 — التفاعلات المستعملة لصناعة البوليمرات (المونومرات ووحدة البناء)'),
('mcq', 6, 'يتبلمر رباعي فلورو إيثين CF₂=CF₂ بالإضافة لينتج بوليمرًا وحدته البنائية –CF₂–CF₂–. ما الذي يميّز الوحدة البنائية من المونومر؟', null, null, '["لها الذرات نفسها، لكن الرابطة الثنائية تحولت إلى رابطة أحادية","فقدت ذرتي فلور في أثناء تكوين البوليمر","فقدت جزيء ماء عند ارتباطها بالوحدات المجاورة","تحتوي على ضعف عدد ذرات المونومر"]'::jsonb, 'فهم', 'مقارنة', 'صعب', 'الكتاب ص 192 — التفاعلات المستعملة لصناعة البوليمرات (المونومرات ووحدة البناء)'),
('mcq', 7, 'يبيّن الشكل الآتي معادلة تحضير نايلون 6,6. ما المونومران اللذان يتكوّن منهما هذا البوليمر؟', null, '[{"src":"qimg/chem22/c5-l5a-nylon66.svg","alt":"معادلة على سطرين. السطر الأول: nHOOC–(CH₂)₄–COOH + nH₂N–(CH₂)₆–NH₂. السطر الثاني: سهم يشير إلى اليمين، ثم وحدة بنائية بين قوسين مربعين، من اليسار: ذرة C مرتبطة بذرة O إلى أعلى برابطة ثنائية، ثم (CH₂)₄، ثم ذرة C مرتبطة بذرة O إلى أعلى برابطة ثنائية، ثم NH، ثم (CH₂)₆، ثم NH، والمجموعات متصلة بروابط أحادية، وتعبر القوسين رابطتان طرفيتان، وأسفل القوس الأيمن n، وبعد القوسين: + 2nH₂O."}]'::jsonb, '["الإيثين و1، 6-ثنائي أمينوهكسان","حمض الأديبيك و1، 6-ثنائي أمينوهكسان","حمض الأديبيك والماء","نايلون 6,6 و1، 6-ثنائي أمينوهكسان"]'::jsonb, 'فهم', 'تحديد المونومرات من معادلة', 'صعب', 'الكتاب ص 193 — البلمرة بالتكثف (نايلون 6,6)'),
('essay', 1, 'عرّف كلًّا من المونومر والوحدة البنائية للبوليمر، ثم حدّد في معادلة البلمرة الآتية: المونومر، والوحدة البنائية، والبوليمر.', null, '[{"src":"qimg/chem22/c5-l5a-ethene-pe.svg","alt":"معادلة: n CH₂=CH₂ (رابطة ثنائية بين مجموعتي CH₂)، ثم سهم يشير إلى اليمين، ثم وحدة بنائية بين قوسين مربعين: مجموعة CH₂ مرتبطة برابطة أحادية بمجموعة CH₂، وتعبر القوسين رابطتان طرفيتان، وأسفل القوس الأيمن الحرف n."}]'::jsonb, null, 'تذكر', 'تعريف وتطبيق', 'متوسط', 'الكتاب ص 192 — التفاعلات المستعملة لصناعة البوليمرات (المونومرات ووحدة البناء)'),
