insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C5-L5-O05'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يبيّن الشكل الآتي الوحدة البنائية للبولي إيثيلين. أيّ وصف لملمسه وذوبانه في الماء صحيح؟', null, '[{"src":"qimg/chem22/c5-l5a-pe.svg","alt":"وحدة بنائية متكررة بين قوسين مربعين: مجموعة CH₂ مرتبطة برابطة أحادية بمجموعة CH₂ أخرى، وتعبر القوسين رابطتان طرفيتان، وأسفل القوس الأيمن الحرف n."}]'::jsonb, '["ملمسه زلق، ويذوب في الماء","ملمسه شمعي، ولا يذوب في الماء","ملمسه شمعي، ويذوب في الماء","ملمسه خشن، ولا يذوب في الماء"]'::jsonb, 'تذكر', 'تذكر خواص', 'سهل', 'الكتاب ص 195 — خواص البوليمرات'),
('mcq', 2, 'لماذا يُستعمل البولي إيثيلين في تغليف أسلاك الكهرباء؟', null, null, '["لأنه يذوب في الماء فيسهل تشكيله","لأنه موصل جيد للكهرباء","لأنه رديء التوصيل للكهرباء وغير نشط كيميائيًّا","لأنه يحتوي على روابط ثنائية تقوّيه"]'::jsonb, 'فهم', 'ربط الخاصية بالاستعمال', 'سهل', 'الكتاب ص 195 — خواص البوليمرات'),
('mcq', 3, 'ما الذي يميّز البوليمرات من الفلزات والمواد الطبيعية الأخرى عند تشكيلها؟', null, null, '["يسهل تشكيلها وسحبها أليافًا رقيقة دون تسخينها إلى درجات حرارة مرتفعة","تحتاج إلى درجات حرارة أعلى مما تحتاج إليه الفلزات","لا يمكن سحبها على شكل ألياف رقيقة أو تشكيلها","تصبح ضعيفة عند تشكيلها في أدوات صغيرة ورقيقة"]'::jsonb, 'تذكر', 'تذكر خاصية', 'متوسط', 'الكتاب ص 195 — خواص البوليمرات'),
('mcq', 4, 'يُستعمل الخشب البلاستيكي المصنوع من نفايات البولي إيثيلين المعاد تدويرها في الأرضيات الخارجية. ما الخاصية التي تجعله مفضّلًا على الخشب الطبيعي؟', null, null, '["يذوب في ماء المطر فيتنظف ذاتيًّا","يحتاج إلى إعادة طلاء مستمرة لحمايته","موصل جيد للحرارة والكهرباء","غير قابل للتآكل ولا يحتاج إلى إعادة طلاء"]'::jsonb, 'تذكر', 'تذكر خاصية', 'سهل', 'الكتاب ص 195 — خواص البوليمرات (الشكل 5-21)'),
('mcq', 5, 'أيّ البوليمرين (I) و(II) في الشكل الآتي تُتوقع أن تكون ذوبانيته في الماء أكبر؟ ولماذا؟', null, '[{"src":"qimg/chem22/c5-l5a-pe-vs-oh.svg","alt":"بوليمران. (I): وحدة بنائية بين قوسين مربعين: CH₂ مرتبطة برابطة أحادية بـ CH₂. (II): وحدة بنائية بين قوسين مربعين: CH₂ مرتبطة برابطة أحادية بـ CH، وتتدلى من CH إلى أسفل رابطة أحادية إلى مجموعة OH. وفي كل منهما تعبر القوسين رابطتان طرفيتان، وأسفل القوس الأيمن الحرف n."}]'::jsonb, '["(I)؛ لأن سلسلته هيدروكربونية غير قطبية","(II)؛ لأن مجموعة OH فيه تكوّن روابط هيدروجينية مع الماء","(II)؛ لأن كتلته المولية أكبر من كتلة (I) دائمًا","(I)؛ لأن وحدته البنائية أصغر وأبسط"]'::jsonb, 'تحليل', 'توقع خاصية من التركيب', 'صعب', 'الكتاب ص 195، 204 — خواص البوليمرات والسؤال 56'),
('mcq', 6, 'توقّع الخواص الفيزيائية والكيميائية للبوليمر الذي تظهر وحدته البنائية في الشكل الآتي.', null, '[{"src":"qimg/chem22/c5-l5a-pp.svg","alt":"وحدة بنائية متكررة بين قوسين مربعين: مجموعة CH₂ مرتبطة برابطة أحادية بمجموعة CH، وتتدلى من CH إلى أسفل رابطة أحادية إلى مجموعة CH₃، وتعبر القوسين رابطتان طرفيتان، وأسفل القوس الأيمن الحرف n."}]'::jsonb, '["لا يذوب في الماء، ورديء التوصيل للكهرباء، وقليل النشاط الكيميائي","يذوب في الماء بسهولة لوجود مجموعة CH₃ القطبية","موصل جيد للكهرباء لاحتوائه على روابط ثنائية كثيرة","نشط كيميائيًّا ويتفاعل بسهولة مع الماء"]'::jsonb, 'تطبيق', 'توقع خواص من التركيب', 'متوسط', 'الكتاب ص 195، 196 — خواص البوليمرات والسؤال 24'),
('mcq', 7, 'يُسمّى بعض البوليمرات البلاستيك الحراري (Thermoplastic)، وهي تسمية مشتقة من الكلمة اليونانية therme بمعنى الحرارة، وplastikos بمعنى قالب أو نموذج. ما الخاصية التي تشير إليها هذه التسمية؟', null, null, '["مقاومتها الكاملة لأي تغير عند التسخين","قدرتها على توصيل الحرارة والكهرباء","إمكانية تشكيلها في قوالب ونماذج بالتسخين","ذوبانها في الماء الساخن"]'::jsonb, 'فهم', 'تفسير مصطلح', 'متوسط', 'الكتاب ص 195 — المفردات: البلاستيك الحراري'),
('essay', 1, 'اذكر أربعًا من خواص البوليمرات التي أدت إلى زيادة الطلب عليها وانتشار استعمالها.', null, null, null, 'تذكر', 'تعداد', 'متوسط', 'الكتاب ص 195 — خواص البوليمرات'),
('essay', 2, 'تعوّض البوليمرات الصناعية كثيرًا من المواد الطبيعية مثل الحجر والخشب والمعادن والصوف والقطن. قوّم هذا الاستبدال بذكر مزيتين وعيبين لاستعمال المواد الصناعية بدلًا من الطبيعية.', null, null, null, 'تقويم', 'تقويم وموازنة', 'صعب', 'الكتاب ص 195، 196 — خواص البوليمرات وتدويرها والسؤال 23'),
('essay', 3, 'يمثّل الشكل الآتي الوحدة البنائية للبولي إيثيلين. (أ) صف تركيب سلسلة البولي إيثيلين. (ب) اذكر أربعًا من خواصه، وفسّر كل خاصية في ضوء تركيبه. (ج) اذكر استعمالين يرتبطان بهذه الخواص.', null, '[{"src":"qimg/chem22/c5-l5a-pe.svg","alt":"وحدة بنائية متكررة بين قوسين مربعين: مجموعة CH₂ مرتبطة برابطة أحادية بمجموعة CH₂ أخرى، وتعبر القوسين رابطتان طرفيتان، وأسفل القوس الأيمن الحرف n."}]'::jsonb, null, 'فهم', 'ربط الخواص بالتركيب', 'صعب', 'الكتاب ص 195 — خواص البوليمرات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C5-L5-O05') and x.type = v.type and x.number = v.number);
