insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C5-L5-O06'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'من أيّ مصدر تُشتق المواد الأولية المستعملة في تصنيع معظم البوليمرات؟', null, null, '["المعادن المستخرجة من الصخور","الوقود الأحفوري","الأخشاب والألياف النباتية","الصوف والحرير الطبيعيان"]'::jsonb, 'تذكر', 'استرجاع حقيقة', 'سهل', 'الكتاب ص 196 — تدوير البوليمرات'),
('mcq', 2, 'لماذا أصبحت عملية تدوير البلاستيك أكثر أهمية في هذه الأيام؟', null, null, '["لأن البلاستيك المعاد تدويره أقوى دائمًا من الفولاذ","لأن البوليمرات تصدأ سريعًا إذا تُركت دون تدوير","لأن تدوير البلاستيك يحوّله إلى وقود أحفوري من جديد","لأن الوقود الأحفوري الذي تُشتق منه موادها الأولية مهدد بالنفاد"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 196 — تدوير البوليمرات'),
('mcq', 3, 'كيف يسهم شراء السلع المصنوعة من البلاستيك المعاد تدويره في المحافظة على الوقود الأحفوري؟', null, null, '["يقلل حجم استعمال الوقود الأحفوري في تصنيع بلاستيك جديد","يزيد كمية الوقود الأحفوري المتكوّن في باطن الأرض","يجعل البوليمرات تُستعمل وقودًا بدلًا من النفط","يمنع استعمال البوليمرات في الصناعات المختلفة"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 196 — تدوير البوليمرات'),
('mcq', 4, 'لماذا تُعدّ إعادة تدوير المواد البلاستيكية عملية صعبة إلى حدٍّ ما؟', null, null, '["لأن البوليمرات تذوب في الماء فيصعب جمعها","لأن البلاستيك يتآكل قبل وصوله إلى مصانع التدوير","لكثرة أنواع البوليمرات المختلفة في المنتجات، فيلزم فرزها وفق مكوناتها","لأن جميع المنتجات البلاستيكية مصنوعة من بوليمر واحد"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 196 — تدوير البوليمرات'),
('mcq', 5, 'يمثّل المخطط الآتي مراحل إنتاج المنتجات البلاستيكية وإعادة تدويرها. أيّ مما يأتي يفسّر من المخطط أن إعادة التدوير تقلل استهلاك الوقود الأحفوري؟', null, '[{"src":"qimg/chem22/c5-l5b-recycle-cycle.svg","alt":"مخطط تدفق من سبعة مربعات مرقمة. في الصف العلوي أربعة مربعات تربطها أسهم تتجه من اليمين إلى اليسار: (1) الوقود الأحفوري، ثم (2) المواد الأولية، ثم (3) تصنيع البوليمر، ثم (4) المنتج البلاستيكي. ومن المربع (4) سهم إلى أسفل نحو المربع (5) النفايات البلاستيكية، ومنه سهم إلى المربع (6) الفرز، ومنه سهم إلى المربع (7) إعادة التدوير. ومن المربع (7) مسار أخضر متقطع يصعد ثم يعود بسهم إلى المربع (4) المنتج البلاستيكي مباشرة دون المرور بالمربعات (1) و(2) و(3)."}]'::jsonb, '["المرحلة (5) تحوّل النفايات البلاستيكية مباشرة إلى وقود أحفوري","المسار المتقطع من (7) إلى (4) يعيد البلاستيك منتجاتٍ دون المرور بالمراحل (1) و(2) و(3)","المرحلة (6) تزيد كمية المواد الأولية المستخرجة من الوقود الأحفوري","المسار من (1) إلى (4) يصبح أقصر كلما زادت النفايات في المرحلة (5)"]'::jsonb, 'تحليل', 'تفسير مخطط', 'صعب', 'الكتاب ص 196 — تدوير البوليمرات'),
('mcq', 6, 'يُصنع الخشب البلاستيكي من البلاستيك المعاد تدويره، مثل زجاجات العصير والحليب ونفايات البولي إيثيلين. ما الذي يوضحه هذا المثال عن أهمية إعادة التدوير؟', null, null, '["يتحوّل البولي إيثيلين بالتدوير إلى خشب طبيعي","لا يمكن الاستفادة من النفايات البلاستيكية إلا وقودًا","الخشب البلاستيكي أسرع تآكلًا من الخشب الطبيعي","تتحول النفايات إلى منتج مفيد دون استهلاك مواد أولية جديدة"]'::jsonb, 'فهم', 'تفسير مثال', 'متوسط', 'الكتاب ص 195، 196 — الخشب البلاستيكي وتدوير البوليمرات'),
('mcq', 7, 'قال طالب: «لا حاجة إلى تدوير البلاستيك ما دامت مواده الأولية رخيصة وسهلة التحضير». أيّ مما يأتي أفضل ردّ علمي على قوله؟', null, null, '["قوله صحيح؛ لأن رخص المواد الأولية يغني عن التدوير دائمًا","قوله صحيح؛ لأن البلاستيك يتحلل سريعًا فلا يتراكم","قوله غير صحيح؛ لأن المواد الأولية مشتقة من وقود أحفوري مهدد بالنفاد","قوله غير صحيح؛ لأن المواد الأولية للبوليمرات غالية جدًّا"]'::jsonb, 'تقويم', 'تقويم ادعاء', 'صعب', 'الكتاب ص 195، 196 — خواص البوليمرات وتدويرها'),
('essay', 1, 'علّل: أصبحت عملية تدوير البلاستيك أكثر أهمية في هذه الأيام، ثم وضّح كيف يسهم المستهلك في المحافظة على الوقود الأحفوري عند شرائه السلع البلاستيكية.', null, null, null, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 196 — تدوير البوليمرات'),
('essay', 2, 'ادرس المخطط الآتي لمراحل إنتاج المنتجات البلاستيكية وإعادة تدويرها، ثم أجب: (أ) ما المراحل التي يتجاوزها المنتج المصنوع من البلاستيك المعاد تدويره؟ (ب) لماذا لا بدّ من المرحلة (6) قبل المرحلة (7)؟ (ج) فسّر كيف يحافظ المسار المتقطع على الوقود الأحفوري.', null, '[{"src":"qimg/chem22/c5-l5b-recycle-cycle.svg","alt":"مخطط تدفق من سبعة مربعات مرقمة. في الصف العلوي أربعة مربعات تربطها أسهم تتجه من اليمين إلى اليسار: (1) الوقود الأحفوري، ثم (2) المواد الأولية، ثم (3) تصنيع البوليمر، ثم (4) المنتج البلاستيكي. ومن المربع (4) سهم إلى أسفل نحو المربع (5) النفايات البلاستيكية، ومنه سهم إلى المربع (6) الفرز، ومنه سهم إلى المربع (7) إعادة التدوير. ومن المربع (7) مسار أخضر متقطع يصعد ثم يعود بسهم إلى المربع (4) المنتج البلاستيكي مباشرة دون المرور بالمربعات (1) و(2) و(3)."}]'::jsonb, null, 'تحليل', 'تفسير مخطط', 'صعب', 'الكتاب ص 196 — تدوير البوليمرات'),
('essay', 3, 'تخطط مدرستك لحملة توعية بإعادة تدوير البلاستيك. اكتب ثلاث حجج علمية تقنع بها الطلاب بأهمية التدوير، ثم اقترح خطوة يقوم بها الطلاب قبل تسليم النفايات البلاستيكية تسهّل تدويرها، مع التعليل.', null, null, null, 'إبداع', 'تصميم حملة توعية', 'صعب', 'الكتاب ص 195، 196 — تدوير البوليمرات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C5-L5-O06') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'تُشتق المواد الأولية المستعملة في تصنيع معظم البوليمرات من الوقود الأحفوري، ولهذا يرتبط تدوير البلاستيك بالمحافظة على هذا الوقود.', '["المعادن مواد طبيعية عوّضت عنها البوليمرات في بعض الاستعمالات، وليست مصدر المواد الأولية لها.","","الأخشاب والقطن مواد طبيعية استعملها الناس قبل البوليمرات الصناعية، وليست مصدر موادها الأولية.","الصوف والحرير مواد طبيعية، أما المواد الأولية لمعظم البوليمرات فتُشتق من الوقود الأحفوري."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.722Z"}'::jsonb),
('mcq', 2, 3, 'المواد الأولية لمعظم البوليمرات مشتقة من الوقود الأحفوري، ولأن هذا الوقود مهدد بالنفاد أصبحت عملية تدوير البلاستيك أكثر أهمية.', '["قوة بعض البوليمرات كالفولاذ خاصية للبوليمر نفسه، ولا علاقة لها بسبب أهمية التدوير.","البوليمرات غير قابلة للصدأ، فهذا ليس سببًا للتدوير.","التدوير يعيد البلاستيك منتجات جديدة ولا يحوّله إلى وقود أحفوري.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-14T13:39:20.722Z"}'::jsonb),
('mcq', 3, 0, 'إعادة التدوير وشراء السلع المصنوعة من البلاستيك المعاد تدويره يقللان من حجم استعمال الوقود الأحفوري، فنحافظ بذلك على هذا النوع من الوقود.', '["","التدوير لا يكوّن وقودًا أحفوريًّا جديدًا، بل يقلل استهلاك الموجود منه.","لا يحوّل التدوير البلاستيك إلى وقود؛ بل يعيد استعماله في منتجات جديدة.","التدوير يُبقي البوليمرات مستعملة في الصناعة، ولا يمنع استعمالها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-14T13:39:20.723Z"}'::jsonb),
('mcq', 4, 2, 'تعد إعادة تدوير البلاستيك صعبة إلى حدٍّ ما نظرًا إلى العدد الكبير من البوليمرات المختلفة في المنتجات، فلا بد من فرز المواد البلاستيكية وفقًا لمكونات البوليمر قبل إعادة استعمالها.', '["معظم البوليمرات الشائعة، مثل البولي إيثيلين، لا تذوب في الماء.","البلاستيك غير قابل للصدأ ولا يتآكل بسهولة، فليس هذا سبب الصعوبة.","","على العكس؛ المنتجات تحتوي على عدد كبير من البوليمرات المختلفة، وهذا سبب الصعوبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.723Z"}'::jsonb),
('mcq', 5, 1, 'المنتج المعاد تدويره يصل إلى المرحلة (4) عبر المسار المتقطع من (7) دون الحاجة إلى وقود أحفوري (1) أو مواد أولية جديدة (2) أو تصنيع بوليمر جديد (3)، فيقل حجم استعمال الوقود الأحفوري.', '["المرحلة (5) تمثّل النفايات فقط، ولا يوجد في المخطط سهم منها إلى الوقود الأحفوري.","","الفرز يجهّز النفايات لإعادة التدوير، ولا يستخرج مواد أولية من الوقود.","مسار التصنيع من الوقود لا يتغير بزيادة النفايات؛ والتوفير يأتي من المسار المتقطع الذي يتجاوزه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-14T13:39:20.723Z"}'::jsonb),
('mcq', 6, 3, 'صناعة الخشب البلاستيكي من نفايات البلاستيك المعاد تدويره تحوّل النفايات إلى منتج مفيد لا يتآكل، ودون الحاجة إلى مواد أولية جديدة مشتقة من الوقود الأحفوري.', '["الخشب البلاستيكي بلاستيك وليس خشبًا طبيعيًّا؛ فالبوليمر لا يتحول إلى خشب.","المثال نفسه يبيّن أن النفايات البلاستيكية تُصنع منها منتجات مفيدة.","الخشب البلاستيكي غير قابل للتآكل، ولا يحتاج إلى إعادة طلاء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-14T13:39:20.723Z"}'::jsonb),
('mcq', 7, 2, 'المواد الأولية للبوليمرات غير مكلفة فعلًا، لكنها مشتقة من الوقود الأحفوري المهدد بالنفاد؛ لذا يبقى التدوير مهمًّا لأنه يقلل استعمال هذا الوقود.', '["رخص المواد الأولية لا يغيّر أن مصدرها وقود أحفوري مهدد بالنفاد.","البلاستيك غير قابل للصدأ أو التآكل بسهولة، فلا يصح القول إنه يتحلل سريعًا.","","الحكم صحيح لكن التعليل خاطئ؛ فالمواد الأولية غير مكلفة، والسبب الحقيقي هو نفاد الوقود الأحفوري."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.723Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تُشتق المواد الأولية المستعملة في تصنيع معظم البوليمرات من الوقود الأحفوري، وهذا الوقود مهدد بالنفاد؛ لذا أصبحت عملية تدوير البلاستيك أكثر أهمية. ويسهم المستهلك بشراء السلع المصنوعة من البلاستيك المعاد تدويره، فيقل حجم استعمال الوقود الأحفوري في تصنيع بلاستيك جديد، ونحافظ بذلك على هذا النوع من الوقود.', '["المواد الأولية لمعظم البوليمرات مشتقة من الوقود الأحفوري","الوقود الأحفوري مهدد بالنفاد","شراء السلع المصنوعة من البلاستيك المعاد تدويره","يقل حجم استعمال الوقود الأحفوري"]'::jsonb, '[]'::jsonb, '[{"element":"مصدر المواد الأولية","marks":1},{"element":"الوقود مهدد بالنفاد","marks":1},{"element":"دور المستهلك: شراء المعاد تدويره","marks":1},{"element":"أثره: تقليل استعمال الوقود الأحفوري","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعليل كامل وتوضيح دور المستهلك وأثره"},{"level":"2–3 درجات","description":"تعليل صحيح مع توضيح ناقص لدور المستهلك أو العكس"},{"level":"1 درجة","description":"ذكر عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعليل أهمية التدوير بأن البلاستيك يصدأ","القول إن التدوير يكوّن وقودًا أحفوريًّا جديدًا","إغفال أن المواد الأولية مشتقة من الوقود الأحفوري"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-14T13:39:20.723Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) يتجاوز المراحل (1) الوقود الأحفوري و(2) المواد الأولية و(3) تصنيع البوليمر، فيعود من إعادة التدوير إلى المنتج البلاستيكي مباشرة. (ب) لأن المنتجات تحتوي على عدد كبير من البوليمرات المختلفة، فلا بد من فرز المواد البلاستيكية وفقًا لمكونات البوليمر قبل إعادة استعمالها. (ج) المواد الأولية لمعظم البوليمرات مشتقة من الوقود الأحفوري المهدد بالنفاد، والمسار المتقطع ينتج منتجات دون مواد أولية جديدة، فيقل حجم استعمال الوقود الأحفوري.', '["المراحل (1) و(2) و(3)","تنوع البوليمرات في المنتجات","الفرز وفق مكونات البوليمر قبل إعادة الاستعمال","لا حاجة إلى مواد أولية جديدة","تقليل استعمال الوقود الأحفوري المهدد بالنفاد"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد المراحل (أ)","marks":2},{"element":"تعليل الفرز (ب)","marks":2},{"element":"تفسير المحافظة على الوقود (ج)","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة عن الأجزاء الثلاثة"},{"level":"3–5 درجات","description":"إجابة صحيحة عن جزأين أو ثلاثة أجزاء ناقصة"},{"level":"1–2 درجة","description":"إجابة صحيحة عن جزء واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار المرحلتين (5) و(6) بدلًا من (1) و(2) و(3)","تعليل الفرز بأن البلاستيك يتآكل","القول إن التدوير يعيد إنتاج الوقود الأحفوري"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-14T13:39:20.723Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الحجج: (1) المواد الأولية لمعظم البوليمرات مشتقة من الوقود الأحفوري المهدد بالنفاد. (2) إعادة التدوير وشراء المنتجات المعاد تدويرها يقللان من حجم استعمال الوقود الأحفوري فنحافظ عليه. (3) يمكن تحويل النفايات البلاستيكية إلى منتجات مفيدة، مثل الخشب البلاستيكي المصنوع من زجاجات العصير والحليب ونفايات البولي إيثيلين، وهو لا يتآكل ولا يحتاج إلى إعادة طلاء. الخطوة: فرز النفايات البلاستيكية حسب رمز إعادة التدوير المطبوع عليها (من 1 إلى 7)؛ لأن المنتجات تحتوي على بوليمرات مختلفة يجب فرزها وفق مكوناتها قبل إعادة استعمالها، والرموز توفر وسيلة سريعة للفرز.', '["حجة نفاد الوقود الأحفوري","حجة تقليل استعمال الوقود الأحفوري","حجة الاستفادة من النفايات (الخشب البلاستيكي)","خطوة الفرز حسب رمز التدوير","تعليل الخطوة بتنوع البوليمرات وسرعة الفرز بالرموز"]'::jsonb, '[]'::jsonb, '[{"element":"ثلاث حجج علمية صحيحة","marks":3},{"element":"خطوة مناسبة","marks":1},{"element":"تعليل الخطوة","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"ثلاث حجج صحيحة وخطوة مناسبة معللة"},{"level":"3–5 درجات","description":"حجتان صحيحتان مع خطوة معللة جزئيًّا"},{"level":"1–2 درجة","description":"حجة واحدة أو خطوة دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر حجج غير علمية أو عامة دون ربطها بالوقود الأحفوري","اقتراح خلط جميع النفايات البلاستيكية معًا","القول إن الرموز تدل على تاريخ الصنع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.723Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
