from (values
('mcq', 1, 'ما الذي تدل عليه الرموز الموحدة المطبوعة على المنتجات البلاستيكية؟', null, null, '["تاريخ صنع المنتج ومدة صلاحيته للاستعمال","عدد مرات إعادة استعمال المنتج المسموح بها","مكونات المنتج من البوليمرات لتسهيل فرزه وإعادة تدويره","درجة الحرارة التي يلين عندها المنتج"]'::jsonb, 'تذكر', 'استرجاع مفهوم', 'سهل', 'الكتاب ص 196 — رموز إعادة التدوير (الشكل 5-22)'),
('mcq', 2, 'يظهر الرمز الآتي على قاع عبوة بلاستيكية. من أيّ بوليمر صُنعت العبوة؟', null, '[{"src":"qimg/chem22/c5-l5b-code-1.svg","alt":"رمز إعادة التدوير: مثلث من ثلاثة أسهم خضراء متتابعة يلاحق بعضها بعضًا، في داخله الرقم 1، ومكتوب تحته الاختصار PETE."}]'::jsonb, '["بولي إيثيلين رباعي فثالات","بولي إيثيلين عالي الكثافة","بولي بروبلين","بولي ستايرين"]'::jsonb, 'فهم', 'قراءة رمز', 'سهل', 'الكتاب ص 196 — رموز إعادة التدوير (الشكل 5-22)'),
('mcq', 3, 'يحمل وعاء مشروبات الرمز الآتي. ما البوليمر المصنوع منه الوعاء، وما وحدته البنائية المتكررة؟', null, '[{"src":"qimg/chem22/c5-l5b-code-5.svg","alt":"رمز إعادة التدوير: مثلث من ثلاثة أسهم خضراء متتابعة يلاحق بعضها بعضًا، في داخله الرقم 5، ومكتوب تحته الاختصار PP."}]'::jsonb, '["بولي ستايرين؛ [–CH₂–CH(C₆H₅)–]ₙ","بولي إيثيلين منخفض الكثافة؛ [–CH₂–CH₂–]ₙ","بولي كلوريد الفينيل؛ [–CH₂–CHCl–]ₙ","بولي بروبلين؛ [–CH₂–CH(CH₃)–]ₙ"]'::jsonb, 'فهم', 'ربط الرمز بالبوليمر', 'متوسط', 'الكتاب ص 196 — رموز إعادة التدوير (الشكل 5-22)، والجدول 5-14 ص 194'),
('mcq', 4, 'يبيّن الشكل الآتي رمزين لإعادة التدوير. ما الذي يميز البوليمر في (أ) من البوليمر في (ب)؟', null, '[{"src":"qimg/chem22/c5-l5b-codes-2-4.svg","alt":"رمزان لإعادة التدوير، كل منهما مثلث من ثلاثة أسهم خضراء متتابعة. الرمز (أ) على اليمين: في داخله الرقم 2 وتحته الاختصار HDPE. الرمز (ب) على اليسار: في داخله الرقم 4 وتحته الاختصار LDPE."}]'::jsonb, '["(أ) بولي إيثيلين و(ب) بولي بروبلين","كلاهما بولي إيثيلين، لكن (أ) عالي الكثافة و(ب) منخفض الكثافة","كلاهما بولي إيثيلين، لكن (أ) منخفض الكثافة و(ب) عالي الكثافة","(أ) بولي ستايرين و(ب) بولي إيثيلين رباعي فثالات"]'::jsonb, 'فهم', 'مقارنة رمزين', 'متوسط', 'الكتاب ص 196 — رموز إعادة التدوير (الشكل 5-22)'),
('mcq', 5, 'منتج بلاستيكي يحمل رمز إعادة التدوير رقم 7. ماذا يدل عليه هذا الرمز؟', null, null, '["أنه مصنوع من البولي ستايرين الشائع","أنه أُعيد تدويره سبع مرات من قبل","أنه مصنوع من بولي إيثيلين منخفض الكثافة","أنه مصنوع من مواد بلاستيكية أخرى غير المرقمة من 1 إلى 6"]'::jsonb, 'تذكر', 'استرجاع حقيقة', 'سهل', 'الكتاب ص 196 — رموز إعادة التدوير (الشكل 5-22)'),
('mcq', 6, 'لماذا لجأت صناعة البلاستيك إلى طباعة رموز موحدة على المنتجات البلاستيكية؟', null, null, '["لأن فرز البلاستيك طويل ومكلف، والرموز توفر وسيلة سريعة لفرزه","لأن الرموز تزيد قوة المنتج ومقاومته للكسر","لأن الرموز تمنع إعادة تدوير المنتجات المختلطة","لأن جميع البوليمرات تُدوَّر معًا دون حاجة إلى فرز"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 196 — رموز إعادة التدوير (الشكل 5-22)'),
('mcq', 7, 'تمثّل الصيغة الآتية الوحدة البنائية لبوليمر صُنعت منه أنابيب بلاستيكية. إذا علمت أن رمز إعادة التدوير الذي يحمل الرقم 3 والحرف V (فينيل) يُستعمل لبولي كلوريد الفينيل، فأيّ رمز يُتوقع أن تحمله الأنابيب؟', null, '[{"src":"qimg/chem22/c5-l5b-pvc.svg","alt":"وحدة بنائية متكررة بين قوسين مربعين: مجموعة CH₂ مرتبطة برابطة أحادية بمجموعة CH، ومن CH رابطة أحادية إلى أسفل تنتهي بذرة Cl، وتعبر القوسين رابطتان طرفيتان، وأسفل القوس الأيمن الحرف n."}]'::jsonb, '["الرقم 1 والاختصار PETE","الرقم 5 والاختصار PP","الرقم 3 والحرف V","الرقم 6 والاختصار PS"]'::jsonb, 'تطبيق', 'ربط التركيب بالرمز', 'متوسط', 'الكتاب ص 196 — رموز إعادة التدوير (الشكل 5-22)، والجدول 5-14 ص 194'),
('essay', 1, 'فسّر كيف تسهم رموز إعادة التدوير الموحدة في تسهيل إعادة تدوير البلاستيك، مبيّنًا لماذا يجب فرز المواد البلاستيكية قبل إعادة استعمالها.', null, null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 196 — رموز إعادة التدوير (الشكل 5-22)'),
('essay', 2, 'يبيّن الشكل الآتي ثلاثة رموز لإعادة التدوير (أ) و(ب) و(ج). (1) اكتب اسم البوليمر أو المادة التي يدل عليها كل رمز. (2) اذكر استعمالًا واحدًا للبوليمر الذي يدل عليه الرمز (ج). (3) ما الفرق بين دلالة الرمز (أ) ودلالة الرمز رقم 4؟', null, '[{"src":"qimg/chem22/c5-l5b-codes-2-3-6.svg","alt":"ثلاثة رموز لإعادة التدوير، كل منها مثلث من ثلاثة أسهم خضراء متتابعة، مرتبة من اليمين إلى اليسار. الرمز (أ): في داخله الرقم 2 وتحته الاختصار HDPE. الرمز (ب): في داخله الرقم 3 وتحته الحرف V. الرمز (ج): في داخله الرقم 6 وتحته الاختصار PS."}]'::jsonb, null, 'فهم', 'قراءة رموز', 'متوسط', 'الكتاب ص 196 — رموز إعادة التدوير (الشكل 5-22)، والجدول 5-14 ص 194'),
('essay', 3, 'وصلت إلى مركز لإعادة التدوير المنتجات المبيّنة في الجدول الآتي مع رموزها. (أ) وزّع المنتجات على حاويات الفرز، واكتب اسم البوليمر الذي يدل عليه رمز كل منتج. (ب) فسّر لماذا لا يصح وضع زجاجة العصير وعلبة الرغوة في حاوية واحدة. (ج) ماذا يعني الرمز 7 على الغلاف؟', '{"headers":["المنتج","الرمز المطبوع عليه"],"rows":[["زجاجة عصير","1 — PETE"],["علبة رغوة لحفظ الطعام","6 — PS"],["لعبة أطفال","4 — LDPE"],["حبل","5 — PP"],["غلاف من مادة مركبة","7"]]}'::jsonb, null, null, 'تحليل', 'فرز وتصنيف', 'صعب', 'الكتاب ص 196 — رموز إعادة التدوير (الشكل 5-22)')
