('mcq', 5, 'يبيّن الشكل الآتي جزءًا من سلسلة بوليمر ناتج بالبلمرة بالإضافة. ما صيغة المونومر الذي صُنع منه؟', null, '[{"src":"qimg/chem22/c5-l5b-pvbr-chain.svg","alt":"جزء من سلسلة بوليمر يبدأ وينتهي بثلاث نقاط: CH₂–CH–CH₂–CH–CH₂–CH مرتبطة بروابط أحادية، وتتدلى من كل مجموعة CH رابطة أحادية إلى أسفل تنتهي بذرة Br."}]'::jsonb, '["CH₃–CH₂Br","CHBr=CHBr","CH₂=CBr₂","CH₂=CHBr"]'::jsonb, 'تطبيق', 'استنتاج المونومر من سلسلة', 'متوسط', 'الكتاب ص 192، 193 — البلمرة بالإضافة والتكثف'),
('mcq', 6, 'يتبلمر المونومر الآتي بالتكثف، فتتحد مجموعة OH في مونومر مع مجموعة COOH في مونومر آخر ويخرج جزيء ماء. ما الوحدة البنائية المتكررة للبوليمر الناتج؟', null, '[{"src":"qimg/chem22/c5-l5b-hydroxyacid.svg","alt":"صيغة بنائية لمونومر من اليسار إلى اليمين: HO–CH₂–CH₂–C–OH بروابط أحادية، وعلى ذرة C ذرة O مرتبطة برابطة ثنائية إلى أعلى، أي أن طرفه الأيمن مجموعة كربوكسيل وطرفه الأيسر مجموعة هيدروكسيل."}]'::jsonb, '["[–HO–CH₂–CH₂–COOH–]ₙ","[–O–CH₂–CH₂–CO–]ₙ","[–CH₂–CH₂–]ₙ","[–O–CH₂–CH₂–COO–]ₙ"]'::jsonb, 'تطبيق', 'رسم البوليمر من مونومر التكثف', 'صعب', 'الكتاب ص 192، 193 — البلمرة بالإضافة والتكثف'),
('mcq', 7, 'يتبلمر المونومر الآتي بالتكثف مكوّنًا روابط أميد بين المونومرات. ما الوحدة البنائية المتكررة للبوليمر الناتج؟', null, '[{"src":"qimg/chem22/c5-l5b-aminoacid.svg","alt":"صيغة بنائية لمونومر من اليسار إلى اليمين: H₂N–(CH₂)₅–C–OH بروابط أحادية، وعلى ذرة C ذرة O مرتبطة برابطة ثنائية إلى أعلى، أي أن طرفه الأيسر مجموعة أمين وطرفه الأيمن مجموعة كربوكسيل."}]'::jsonb, '["[–NH–(CH₂)₅–CO–]ₙ","[–NH₂–(CH₂)₅–COOH–]ₙ","[–NH–(CH₂)₅–COO–]ₙ","[–NH–(CH₂)₅–NH–]ₙ"]'::jsonb, 'تطبيق', 'رسم البوليمر من مونومر التكثف', 'متوسط', 'الكتاب ص 192، 193 — البلمرة بالإضافة والتكثف (نايلون 6,6)'),
('essay', 1, 'يبيّن الشكل الآتي مونومرين (a) و(b) يتبلمر كل منهما بالإضافة. (أ) ارسم الصيغة البنائية للبوليمر الناتج من كل منهما، مبيّنًا الوحدة البنائية بين قوسين مع n. (ب) ارسم جزءًا من سلسلة البوليمر الناتج من (a) يحتوي على ثلاث وحدات متتالية. (ج) ما الذي يحدث للرابطة الثنائية في أثناء البلمرة؟', null, '[{"src":"qimg/chem22/c5-l5b-monomers-e1.svg","alt":"مونومران. (a): مجموعة CH₂ مرتبطة برابطة ثنائية بمجموعة CHF. (b): مجموعة CH₂ مرتبطة برابطة ثنائية بذرة كربون C، ومن ذرة C رابطة أحادية إلى أعلى تنتهي بمجموعة CH₃ ورابطة أحادية إلى أسفل تنتهي بمجموعة CH₃."}]'::jsonb, null, 'تطبيق', 'رسم صيغة بنائية', 'متوسط', 'الكتاب ص 192، 193 — البلمرة بالإضافة والتكثف'),
('essay', 2, 'يبيّن الشكل الآتي الوحدتين البنائيتين لبوليمرين (I) و(II). (أ) اكتب صيغة المونومر أو المونومرات التي يُصنع منها كل بوليمر. (ب) صنّف تفاعل البلمرة في كل منهما إلى إضافة أو تكثف مع التعليل. (ج) ما الجزيء الصغير الذي يخرج عند تكوين (II)، وما الرابطة الجديدة المتكوّنة؟', null, '[{"src":"qimg/chem22/c5-l5b-units-e2.svg","alt":"وحدتان بنائيتان. (I): بين قوسين مربعين مجموعة CH₂ مرتبطة برابطة أحادية بمجموعة CF₂، وتعبر القوسين رابطتان طرفيتان، وأسفل القوس الأيمن n. (II): بين قوسين مربعين، من اليسار إلى اليمين: NH ثم (CH₂)₆ ثم NH ثم ذرة C عليها ذرة O برابطة ثنائية إلى أعلى، ثم (CH₂)₈ ثم ذرة C عليها ذرة O برابطة ثنائية إلى أعلى، والروابط بينها أحادية، وتعبر القوسين رابطتان طرفيتان، وأسفل القوس الأيمن n."}]'::jsonb, null, 'تحليل', 'استنتاج المونومر من البوليمر', 'صعب', 'الكتاب ص 192، 193 — البلمرة بالإضافة والتكثف، والسؤال 54 ص 204'),
('essay', 3, 'يتبلمر المونومران HO–CH₂–CH₂–OH وHOOC–(CH₂)₄–COOH بالتكثف. (أ) اكتب معادلة التفاعل باستعمال n، موضّحًا الوحدة البنائية المتكررة بين قوسين. (ب) ما اسم الرابطة الجديدة المتكوّنة بين المونومرين؟ (ج) كم جزيء ماء يتكوّن مقابل كل رابطة جديدة؟ ولماذا يُصنَّف التفاعل تكثفًا؟', null, null, null, 'تطبيق', 'كتابة معادلة بلمرة بالتكثف', 'صعب', 'الكتاب ص 192، 193 — البلمرة بالإضافة والتكثف، والشكل 5-20')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
