('mcq', 1, 'في الشكل الآتي بوليمران (I) و(II). ما المجموعة الوظيفية التي تجعل (II) أكثر ذوبانًا في الماء من (I)، وكيف تتفاعل مع جزيئات الماء؟', null, '[{"src":"qimg/chem22/c5-l5b-pp-vs-cooh.svg","alt":"بوليمران. (I): وحدة بنائية بين قوسين مربعين: CH₂ مرتبطة برابطة أحادية بـ CH، ومن CH رابطة أحادية إلى أسفل تنتهي بمجموعة CH₃. (II): وحدة بنائية بين قوسين مربعين: CH₂ مرتبطة برابطة أحادية بـ CH، ومن CH رابطة أحادية إلى أسفل تنتهي بمجموعة COOH. وفي كل منهما وتعبر القوسين رابطتان طرفيتان، وأسفل القوس الأيمن الحرف n."}]'::jsonb, '["مجموعة الميثيل CH₃؛ تكوّن روابط هيدروجينية مع الماء","مجموعة الكربوكسيل COOH؛ تجعل السلسلة غير قطبية","مجموعة الكربوكسيل COOH؛ تكوّن روابط هيدروجينية مع الماء","مجموعة الميثيل CH₃؛ تجعل السلسلة أكثر قطبية"]'::jsonb, 'تحليل', 'توقع خاصية من المجموعات الوظيفية', 'متوسط', 'الكتاب ص 195، 196، 204 — خواص البوليمرات والسؤالان 24 و56'),
('mcq', 2, 'رتّب البوليمرات (A) و(B) و(C) في الشكل الآتي تصاعديًّا حسب ذوبانيتها المتوقعة في الماء.', null, '[{"src":"qimg/chem22/c5-l5b-three-polymers.svg","alt":"ثلاثة بوليمرات. (A): وحدة بنائية بين قوسين مربعين: CH₂ مرتبطة برابطة أحادية بـ CH₂. (B): وحدة بين قوسين: CH₂ مرتبطة بـ CH، ومن CH رابطة أحادية إلى أسفل تنتهي بمجموعة OCH₃. (C): وحدة بين قوسين: CH₂ مرتبطة بـ CH، ومن CH رابطة أحادية إلى أسفل تنتهي بمجموعة OH. وفي كل منها وتعبر القوسين رابطتان طرفيتان، وأسفل القوس الأيمن الحرف n."}]'::jsonb, '["(A) < (B) < (C)","(C) < (B) < (A)","(B) < (A) < (C)","(A) < (C) < (B)"]'::jsonb, 'تحليل', 'ترتيب خاصية', 'صعب', 'الكتاب ص 195، 196، 204 — خواص البوليمرات والسؤالان 24 و56، وص 199 — الكحولات والإيثرات'),
('mcq', 3, 'تمثّل الصيغة الآتية الوحدة البنائية لبوليمر يُستعمل طلاءً غير لاصق لأدوات المطبخ. أيّ مجموعة من الخواص يُتوقع أن يتصف بها اعتمادًا على تركيبه؟', null, '[{"src":"qimg/chem22/c5-l5b-ptfe.svg","alt":"وحدة بنائية متكررة بين قوسين مربعين: ذرتا كربون C بينهما رابطة أحادية، وعلى كل ذرة كربون ذرة فلور F برابطة أحادية إلى أعلى وذرة فلور F برابطة أحادية إلى أسفل، وتعبر القوسين رابطتان طرفيتان، وأسفل القوس الأيمن الحرف n."}]'::jsonb, '["يذوب في الماء، ونشط كيميائيًّا، وموصل جيد للكهرباء","لا يذوب في الماء، ويتفاعل بالإضافة بسهولة، وموصل للكهرباء","يذوب في الماء بالروابط الهيدروجينية، وغير نشط، ورديء التوصيل","لا يذوب في الماء، وغير نشط كيميائيًّا، ورديء التوصيل للكهرباء"]'::jsonb, 'تحليل', 'توقع خواص من التركيب', 'متوسط', 'الكتاب ص 195، 196، 204 — خواص البوليمرات والسؤالان 24 و56، والخط الزمني ص 193'),
('mcq', 4, 'تتكرر في سلسلة النايلون مجموعات أميد –CO–NH–، أما البولي إيثيلين فسلسلة ألكان غير قطبية. إذا علمت أن قوة الألياف تزداد بزيادة قوى التجاذب بين السلاسل المتجاورة، فما التفسير الأرجح لقوة ألياف النايلون مقارنة بالبولي إيثيلين؟', null, null, '["احتواء سلسلته على روابط ثنائية C=C كثيرة تقوّي الألياف","تكوّن روابط هيدروجينية بين مجموعات N–H وC=O في السلاسل المتجاورة","كون سلسلته غير قطبية تمامًا مثل البولي إيثيلين","تكوّن روابط أيونية بين ذرات الكربون في السلاسل المتجاورة"]'::jsonb, 'تحليل', 'تفسير خاصية بالتركيب', 'صعب', 'الكتاب ص 195، 196، 204 — خواص البوليمرات والسؤالان 24 و56، وص 193 — النايلون'),
('mcq', 5, 'يُستعمل بولي كلوريد الفينيل [–CH₂–CHCl–]ₙ في صناعة أنابيب المياه وملابس المطر. ما الخاصية المتوقعة من تركيبه التي تجعله مناسبًا لهذين الاستعمالين؟', null, null, '["لا يذوب في الماء؛ لعدم احتوائه على مجموعات تكوّن روابط هيدروجينية معه","يذوب في الماء ببطء؛ لاحتوائه على ذرات الكلور القطبية","يمتص الماء؛ لاحتواء سلسلته على روابط ثنائية كثيرة","يتفاعل مع الماء بالإضافة؛ لأن سلسلته غير مشبعة"]'::jsonb, 'تحليل', 'ربط الاستعمال بالتركيب', 'متوسط', 'الكتاب ص 195، 196، 204 — خواص البوليمرات والسؤالان 24 و56، والجدول 5-14 ص 194'),
('mcq', 6, 'تريد شركة تصنيع مادة بوليمرية تمتص كميات كبيرة من الماء. أيّ الوحدات البنائية الآتية يُتوقع أن تكون الأنسب؟', null, null, '["[–CH₂–CH(CH₃)–]ₙ","[–CF₂–CF₂–]ₙ","[–CH₂–CH(C₆H₅)–]ₙ","[–CH₂–CH(COOH)–]ₙ"]'::jsonb, 'تقويم', 'اختيار بوليمر لغرض', 'متوسط', 'الكتاب ص 195، 196، 204 — خواص البوليمرات والسؤالان 24 و56'),
('mcq', 7, 'يحتوي البولي ستايرين على حلقات بنزين متصلة بسلسلة هيدروكربونية مشبعة. ما الخاصية المتوقعة له عند وضعه في الماء؟', null, null, '["يذوب؛ لأن حلقة البنزين قطبية جدًّا","لا يذوب؛ لأن السلسلة والحلقات غير قطبية","يذوب؛ لأنه يكوّن روابط هيدروجينية مع الماء","يتفاعل مع الماء؛ لأن حلقات البنزين نشطة جدًّا"]'::jsonb, 'فهم', 'توقع خاصية من التركيب', 'سهل', 'الكتاب ص 195، 196، 204 — خواص البوليمرات والسؤالان 24 و56، والجدول 5-14 ص 194'),
('essay', 1, 'يبيّن الشكل الآتي الوحدات البنائية لثلاثة بوليمرات (أ) و(ب) و(ج). اعتمادًا على تركيبها ومجموعاتها الوظيفية، حدّد مع التعليل: (1) البوليمر الأكثر ذوبانًا في الماء. (2) البوليمر الأنسب طلاءً غير لاصق ومقاومًا للمواد الكيميائية في أواني الطبخ. (3) البوليمر الذي يكوّن أليافًا قوية بروابط هيدروجينية بين سلاسله.', null, '[{"src":"qimg/chem22/c5-l5b-three-b.svg","alt":"ثلاث وحدات بنائية بين أقواس مربعة مع n. (أ): ذرتا كربون C بينهما رابطة أحادية، وعلى كل ذرة كربون ذرة فلور F برابطة أحادية إلى أعلى وذرة فلور F برابطة أحادية إلى أسفل. (ب): CH₂ مرتبطة بـ CH، ومن CH رابطة أحادية إلى أسفل تنتهي بمجموعة COOH. (ج): من اليسار إلى اليمين NH ثم (CH₂)₆ ثم NH ثم ذرة C عليها ذرة O برابطة ثنائية إلى أعلى، ثم (CH₂)₄ ثم ذرة C عليها ذرة O برابطة ثنائية إلى أعلى، والروابط بينها أحادية. وفي كل وحدة تعبر القوسين رابطتان طرفيتان."}]'::jsonb, null, 'تحليل', 'توقع خواص من المجموعات الوظيفية', 'صعب', 'الكتاب ص 195، 196، 204 — خواص البوليمرات والسؤالان 24 و56، وص 193'),
('essay', 2, 'قارن بين البولي إيثيلين [–CH₂–CH₂–]ₙ وبولي أكريلونيتريل [–CH₂–CH(C≡N)–]ₙ من حيث: (أ) قطبية المجموعات في السلسلة. (ب) قوى التجاذب المتوقعة بين السلاسل. (ج) أيهما يُتوقع أن يحتاج إلى درجة حرارة أعلى لكي يلين؟ علّل، علمًا أن البوليمر يلين عند تسخينه حين تكفي الطاقة الحرارية للتغلب على قوى التجاذب بين سلاسله.', null, null, null, 'تحليل', 'مقارنة وتوقع', 'متوسط', 'الكتاب ص 195، 196، 204 — خواص البوليمرات والسؤالان 24 و56، والجدول 5-14 ص 194'),
('essay', 3, 'اقترح وحدة بنائية متكررة لكل من البوليمرين الآتيين، وعلّل اختيارك اعتمادًا على المجموعات الوظيفية: (أ) بوليمر يذوب في الماء لصنع أكياس تذوب عند غسلها. (ب) بوليمر لتغليف أسلاك الكهرباء لا يذوب في الماء ولا يتفاعل بسهولة. ثم اكتب صيغة المونومر لكل منهما.', null, null, null, 'إبداع', 'تصميم بوليمر لغرض', 'صعب', 'الكتاب ص 195، 196، 204 — خواص البوليمرات والسؤالان 24 و56')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C5-L5-O09') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'البوليمر (II) يحمل مجموعات كربوكسيل COOH قطبية على طول السلسلة تكوّن روابط هيدروجينية مع الماء، أما (I) فيحمل مجموعات CH₃ غير قطبية؛ لذا يُتوقع أن تكون ذوبانية (II) في الماء أكبر.', '["مجموعة CH₃ موجودة في (I) لا في (II)، وهي غير قطبية ولا تكوّن روابط هيدروجينية.","مجموعة الكربوكسيل قطبية، فهي تزيد قطبية السلسلة ولا تجعلها غير قطبية.","","مجموعة CH₃ غير قطبية، وهي التي تجعل (I) قليل الذوبان في الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.727Z"}'::jsonb),
('mcq', 2, 0, '(A) سلسلة ألكان غير قطبية لا تذوب في الماء؛ و(B) يحمل مجموعة إيثر –OCH₃ قطبية قليلًا؛ و(C) يحمل مجموعات OH تكوّن روابط هيدروجينية مع الماء كالكحولات؛ لذا فالترتيب التصاعدي (A) < (B) < (C).', '["","هذا الترتيب معكوس؛ فالسلسلة الهيدروكربونية (A) أقلها ذوبانًا لا أكثرها.","(B) يحمل مجموعة إيثر قطبية، فذوبانيته المتوقعة أكبر من سلسلة الألكان غير القطبية (A).","مجموعة OH في (C) تكوّن روابط هيدروجينية مع الماء أقوى أثرًا من ذرة أكسجين الإيثر في (B)، كما تكون الكحولات أكثر ذوبانًا من الإيثرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.727Z"}'::jsonb),
('mcq', 3, 3, 'السلسلة مشبعة بروابط أحادية C–C وC–F فلا تتفاعل بسهولة (غير نشطة)، ولا تحتوي على مجموعات تكوّن روابط هيدروجينية مع الماء فلا تذوب فيه، وهي مركب جزيئي بلا أيونات فهي رديئة التوصيل للكهرباء.', '["السلسلة لا تحتوي على مجموعات OH أو NH، ولا على أيونات تجعلها موصلة.","جميع روابط السلسلة أحادية (مشبعة)، فلا تحدث لها تفاعلات إضافة، ولا أيونات فيها لتوصيل الكهرباء.","لا توجد فيه ذرات H مرتبطة بـ O أو N، فلا يكوّن روابط هيدروجينية مع الماء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.727Z"}'::jsonb),
('mcq', 4, 1, 'مجموعة الأميد تحتوي على ذرة H مرتبطة بذرة N، وعلى ذرة O في C=O، فتتكوّن روابط هيدروجينية بين السلاسل المتجاورة، فتزداد قوى التجاذب بينها وتكون الألياف قوية؛ أما سلاسل البولي إيثيلين غير القطبية فقوى التجاذب بينها ضعيفة.', '["سلسلة النايلون لا تحتوي على روابط ثنائية C=C؛ فالرابطة الثنائية فيه C=O ضمن مجموعة الأميد.","","مجموعات الأميد قطبية، فسلسلة النايلون ليست غير قطبية كالبولي إيثيلين.","لا تتكوّن روابط أيونية بين ذرات الكربون؛ فالنايلون مركب جزيئي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.727Z"}'::jsonb),
('mcq', 5, 0, 'سلسلة PVC مشبعة وتشبه السلاسل الهيدروكربونية، ولا تحمل مجموعات OH أو NH تكوّن روابط هيدروجينية مع الماء؛ لذا لا يذوب فيه، فيصلح لأنابيب المياه وملابس المطر.', '["","لو ذاب في الماء ولو ببطء لما صلح لأنابيب المياه؛ وذرات Cl لا تكوّن روابط هيدروجينية مع الماء.","سلسلة البوليمر مشبعة لا تحتوي على روابط ثنائية بعد البلمرة بالإضافة.","السلسلة مشبعة بروابط أحادية، فلا يحدث لها تفاعل إضافة الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.728Z"}'::jsonb),
('mcq', 6, 3, 'مجموعات الكربوكسيل COOH القطبية على طول السلسلة تكوّن روابط هيدروجينية مع جزيئات الماء فتجذبه، أما البدائل الأخرى فتحمل مجموعات غير قطبية.', '["مجموعة CH₃ غير قطبية، فالبولي بروبلين لا يجذب الماء.","هذا البوليمر لا يحمل مجموعات تكوّن روابط هيدروجينية مع الماء، ويُستعمل طلاءً غير لاصق.","حلقة البنزين غير قطبية، فالبولي ستايرين لا يجذب الماء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.728Z"}'::jsonb),
('mcq', 7, 1, 'البولي ستايرين مكوّن من الكربون والهيدروجين فقط، فسلسلته وحلقاته غير قطبية ولا تكوّن روابط هيدروجينية مع الماء؛ لذا لا يذوب فيه.', '["حلقة البنزين هيدروكربون غير قطبي.","","لا يحتوي على ذرات H مرتبطة بـ O أو N، فلا يكوّن روابط هيدروجينية مع الماء.","حلقة البنزين ثابتة نسبيًّا ولا تتفاعل مع الماء، ولذلك يُستعمل في حاويات حفظ الطعام."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.728Z"}'::jsonb),
('essay', 1, null::int, null, null, '(1) البوليمر (ب)؛ لأنه يحمل مجموعة كربوكسيل COOH في كل وحدة، وهي مجموعة قطبية تكوّن روابط هيدروجينية مع الماء. (2) البوليمر (أ)؛ لأن سلسلته مشبعة لا تحتوي إلا على روابط C–C وC–F، ولا يحمل مجموعات تتفاعل بسهولة أو تكوّن روابط هيدروجينية، فهو غير نشط ولا يذوب في الماء. (3) البوليمر (ج)؛ لأنه يحتوي على مجموعات أميد –CO–NH–، فتتكوّن روابط هيدروجينية بين N–H في سلسلة وC=O في سلسلة مجاورة فتقوى الألياف (وهو النايلون).', '["(1) البوليمر (ب)","تعليل: COOH قطبية تكوّن روابط هيدروجينية مع الماء","(2) البوليمر (أ)","تعليل: سلسلة مشبعة غير نشطة لا تذوب","(3) البوليمر (ج)","تعليل: روابط هيدروجينية بين مجموعات الأميد"]'::jsonb, '[]'::jsonb, '[{"element":"الاختيار (1) مع التعليل","marks":2},{"element":"الاختيار (2) مع التعليل","marks":2},{"element":"الاختيار (3) مع التعليل","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"ثلاثة اختيارات صحيحة معللة"},{"level":"3–5 درجات","description":"اختياران صحيحان معللان أو ثلاثة بتعليل ناقص"},{"level":"1–2 درجة","description":"اختيار واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار (أ) للذوبان لأن ذرات F قطبية","تعليل قوة النايلون بروابط تساهمية بين السلاسل","إغفال ربط الخاصية بالمجموعة الوظيفية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.728Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) البولي إيثيلين سلسلة ألكان غير قطبية، أما بولي أكريلونيتريل فيحمل في كل وحدة مجموعة نيتريل C≡N قطبية. (ب) بين سلاسل البولي إيثيلين قوى تشتت ضعيفة فقط، أما بين سلاسل بولي أكريلونيتريل فتوجد إضافة إليها قوى تجاذب بين الأقطاب (ثنائية القطب) بسبب مجموعات C≡N، فالتجاذب أقوى. (ج) بولي أكريلونيتريل؛ لأن قوى التجاذب الأقوى بين سلاسله تحتاج إلى طاقة أكبر للتغلب عليها، فيحتاج إلى درجة حرارة أعلى ليلين.', '["البولي إيثيلين غير قطبي","C≡N مجموعة قطبية","قوى تشتت ضعيفة في البولي إيثيلين","قوى ثنائية القطب إضافية في بولي أكريلونيتريل","بولي أكريلونيتريل يلين عند درجة حرارة أعلى مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"المقارنة في القطبية","marks":2},{"element":"المقارنة في قوى التجاذب","marks":2},{"element":"التوقع مع التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة وتوقع معلل"},{"level":"3–4 درجات","description":"مقارنة صحيحة في معيارين دون تعليل كافٍ للتوقع"},{"level":"1–2 درجة","description":"مقارنة صحيحة في معيار واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار C≡N رابطة غير قطبية لأنها بين ذرتين غير فلزيتين","ربط درجة التليين بطول السلسلة فقط","الخلط بين الروابط داخل الجزيء وقوى التجاذب بين السلاسل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.728Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) [–CH₂–CH(COOH)–]ₙ؛ لأن مجموعات الكربوكسيل COOH القطبية على طول السلسلة تكوّن روابط هيدروجينية مع الماء فيذوب البوليمر فيه (وتُقبل وحدة تحمل مجموعات OH مثل [–CH₂–CH(OH)–]ₙ). المونومر: CH₂=CHCOOH. (ب) [–CH₂–CH₂–]ₙ (البولي إيثيلين)؛ لأنه سلسلة ألكان طويلة غير قطبية لا تكوّن روابط هيدروجينية مع الماء فلا يذوب فيه، ومشبعة فهي غير نشطة كيميائيًّا، ولا تحتوي على أيونات أو إلكترونات حرة فهي رديئة التوصيل للكهرباء. المونومر: CH₂=CH₂.', '["وحدة تحمل مجموعة قطبية (COOH أو OH) للبوليمر الذائب","تعليل بالروابط الهيدروجينية مع الماء","وحدة هيدروكربونية مشبعة للعازل","تعليل: غير قطبي، غير نشط، رديء التوصيل","صيغتا المونومرين الصحيحتان"]'::jsonb, '[]'::jsonb, '[{"element":"اقتراح (أ) مع التعليل","marks":2},{"element":"اقتراح (ب) مع التعليل","marks":2},{"element":"صيغتا المونومرين","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"اقتراحان مناسبان معللان مع المونومرين"},{"level":"3–5 درجات","description":"اقتراحان مناسبان مع تعليل أو مونومر ناقص"},{"level":"1–2 درجة","description":"اقتراح واحد مناسب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اقتراح بوليمر هيدروكربوني للغرض (أ)","كتابة مونومر بلا رابطة ثنائية لبوليمر إضافة","تعليل العزل الكهربائي بعدم الذوبان فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-14T13:39:20.729Z"}'::jsonb)
